import React, { useState, useRef } from 'react';
import { Send, Search, CheckCircle, ShieldQuestion, Scale, Users, ShieldAlert, HeartHandshake, ChevronRight, FileUp, ClipboardList, AlertCircle, ArrowLeft, ArrowRight, User, MapPin, X, FileText, ImageIcon, Loader2 } from 'lucide-react';
import { UrgencyLevel } from '../types';

interface UploadedFile {
  id: string;
  file: File;
  progress: number;
  error?: string;
}

const LegalAid: React.FC = () => {
  const [submitted, setSubmitted] = useState(false);
  const [step, setStep] = useState(1);
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    location: '',
    category: 'Criminal Defense & Representation',
    description: '',
    urgency: UrgencyLevel.LOW,
    isIndigent: false,
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files).map(f => {
        const id = Math.random().toString(36).substring(7);
        let error = "";
        if (f.size > 5 * 1024 * 1024) error = "File too large (>5MB)";
        const allowedTypes = ['application/pdf', 'image/jpeg', 'image/png', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
        if (!allowedTypes.includes(f.type)) error = "Unsupported format (Use PDF, JPG, PNG, or DOC)";

        return { id, file: f, progress: error ? 0 : 0, error };
      });

      setFiles(prev => [...prev, ...newFiles]);

      // Simulate upload progress for valid files
      newFiles.forEach((nf) => {
        if (!nf.error) {
          let p = 0;
          const interval = setInterval(() => {
            p += Math.floor(Math.random() * 30) + 10;
            if (p >= 100) {
              p = 100;
              clearInterval(interval);
            }
            setFiles(current => 
              current.map(item => item.id === nf.id ? { ...item, progress: p } : item)
            );
          }, 400);
        }
      });
    }
  };

  const removeFile = (id: string) => {
    setFiles(prev => prev.filter(f => f.id !== id));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (step < 3) {
      setStep(step + 1);
    } else {
      setTimeout(() => {
        setSubmitted(true);
      }, 1000);
    }
  };

  const legalServices = [
    {
      title: "Criminal Defense",
      icon: <Scale className="text-primary" size={28} />,
      items: [
        "Court representation for capital offenders (High & Chief Magistrates Courts)",
        "Bail applications and police bond assistance",
        "Plea bargain program (Special focus on Kayunga)",
        "Self-representation training for prisoners",
        "Integrated case intake and tracking system"
      ]
    },
    {
      title: "Civil Legal Aid",
      icon: <Users className="text-yellow-600" size={28} />,
      items: [
        "Land and property disputes resolution",
        "Domestic relations and family law cases",
        "Alternative Dispute Resolution (ADR)",
        "Professional mediation services",
        "General legal counseling and guidance"
      ]
    },
    {
      title: "Juvenile Justice Program",
      icon: <ShieldAlert className="text-blue-600" size={28} />,
      items: [
        "Services for Naguru & Gulu Remand Homes",
        "Representation for child offenders",
        "Children's rights awareness campaigns",
        "Family mediation for child-related cases"
      ]
    },
    {
      title: "Refugee Legal Assistance",
      icon: <HeartHandshake className="text-green-600" size={28} />,
      items: [
        "Enhanced access to justice for refugees",
        "Legal documentation and registration assistance",
        "Human rights and legal education",
        "Protection of refugee rights in courts"
      ]
    }
  ];

  const steps = [
    { id: 1, name: 'Personal Info', icon: <User size={18} /> },
    { id: 2, name: 'Case Details', icon: <ClipboardList size={18} /> },
    { id: 3, name: 'Verification', icon: <FileUp size={18} /> },
  ];

  const suggestedDocs = [
    { name: "National ID / Passport", desc: "Proof of identity (Mandatory)" },
    { name: "Police Abstract", desc: "For criminal matters" },
    { name: "Land Title / Agreement", desc: "For property disputes" },
    { name: "LC1 Recommendation", desc: "Proof of indigence/residence" }
  ];

  return (
    <div className="bg-white min-h-screen">
      <div className="bg-primary text-white py-24 px-4 relative overflow-hidden">
         <div className="absolute inset-0 opacity-10">
          <img src="https://images.unsplash.com/photo-1505664194779-8beaceb93744?auto=format&fit=crop&q=80" alt="court" className="w-full h-full object-cover" />
        </div>
        <div className="max-w-5xl mx-auto text-center relative z-10">
          <h1 className="text-4xl lg:text-6xl font-bold mb-6 text-white font-serif">Comprehensive Legal Aid</h1>
          <p className="text-xl text-blue-100 max-w-3xl mx-auto">
            Licensed by the Uganda Law Council to provide pro-bono services to the poor and needy. We speak up for those who cannot speak for themselves.
          </p>
        </div>
      </div>

      <section className="py-20 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="text-center mb-16">
            <h2 className="text-3xl font-bold text-gray-900 mb-4">Our Legal Aid Programs</h2>
            <p className="text-gray-500">Structured support for indigent clients across the Justice, Law and Order Sector.</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-20">
            {legalServices.map((service, idx) => (
              <div key={idx} className="bg-white rounded-3xl p-8 shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
                <div className="flex items-center mb-6">
                  <div className="bg-gray-50 p-4 rounded-2xl mr-4">
                    {service.icon}
                  </div>
                  <h3 className="text-2xl font-bold text-gray-900 font-serif">{service.title}</h3>
                </div>
                <ul className="space-y-3">
                  {service.items.map((item, i) => (
                    <li key={i} className="flex items-start text-gray-600">
                      <ChevronRight className="text-primary mt-1 mr-2 flex-shrink-0" size={16} />
                      <span className="text-sm lg:text-base leading-tight">{item}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>

          <div id="intake-portal" className="grid grid-cols-1 lg:grid-cols-3 gap-12 scroll-mt-24">
            <div className="lg:col-span-2">
              {!submitted ? (
                <div className="bg-white rounded-3xl shadow-xl border border-gray-100 p-8 lg:p-12">
                  <div className="mb-10">
                    <h2 className="text-2xl font-bold mb-6 font-serif">Public Case Intake Portal</h2>

                    <div className="flex items-center space-x-4">
                      {steps.map((s, idx) => (
                        <React.Fragment key={s.id}>
                          <div className="flex items-center">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${step >= s.id ? 'bg-primary text-white' : 'bg-gray-100 text-gray-400'}`}>
                              {step > s.id ? <CheckCircle size={16} /> : s.id}
                            </div>
                            <span className={`ml-2 text-xs font-bold uppercase tracking-wider hidden sm:block ${step >= s.id ? 'text-primary' : 'text-gray-400'}`}>
                              {s.name}
                            </span>
                          </div>
                          {idx < steps.length - 1 && <div className={`flex-1 h-px w-8 sm:w-12 ${step > s.id ? 'bg-primary' : 'bg-gray-200'}`}></div>}
                        </React.Fragment>
                      ))}
                    </div>
                  </div>

                  <form onSubmit={handleSubmit} className="space-y-8">
                    {step === 1 && (
                      <div className="space-y-6 animate-in fade-in slide-in-from-right duration-300">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div className="space-y-2">
                            <label className="text-sm font-bold text-gray-700 flex items-center"><User size={14} className="mr-2" /> Full Legal Name</label>
                            <input required type="text" className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-primary outline-none transition-all" placeholder="Enter full name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} />
                          </div>
                          <div className="space-y-2">
                            <label className="text-sm font-bold text-gray-700 flex items-center"><AlertCircle size={14} className="mr-2" /> Phone Number</label>
                            <input required type="text" className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-primary outline-none transition-all" placeholder="+256..." value={formData.phone} onChange={(e) => setFormData({...formData, phone: e.target.value})} />
                          </div>
                        </div>
                        <div className="space-y-2">
                          <label className="text-sm font-bold text-gray-700 flex items-center"><MapPin size={14} className="mr-2" /> Resident District / Village</label>
                          <input required type="text" className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-primary outline-none transition-all" placeholder="e.g. Kayunga, Gulu, etc." value={formData.location} onChange={(e) => setFormData({...formData, location: e.target.value})} />
                        </div>
                      </div>
                    )}

                    {step === 2 && (
                      <div className="space-y-6 animate-in fade-in slide-in-from-right duration-300">
                        <div className="space-y-2">
                          <label className="text-sm font-bold text-gray-700">Case Category</label>
                          <select className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-primary outline-none transition-all bg-white" value={formData.category} onChange={(e) => setFormData({...formData, category: e.target.value})}>
                            <option>Criminal Defense & Representation</option>
                            <option>Civil Law & Property Disputes</option>
                            <option>Juvenile Justice (Naguru/Gulu)</option>
                            <option>Refugee Legal Assistance</option>
                            <option>Mediation & Counseling</option>
                          </select>
                        </div>
                        <div className="space-y-2">
                          <label className="text-sm font-bold text-gray-700">Level of Urgency</label>
                          <div className="grid grid-cols-3 gap-3">
                            {[UrgencyLevel.LOW, UrgencyLevel.MEDIUM, UrgencyLevel.HIGH].map((u) => (
                              <button key={u} type="button" onClick={() => setFormData({...formData, urgency: u})} className={`py-3 rounded-xl text-xs font-bold border-2 transition-all ${formData.urgency === u ? 'border-primary bg-blue-50 text-primary' : 'border-gray-100 text-gray-500 hover:border-gray-200'}`}>
                                {u}
                              </button>
                            ))}
                          </div>
                        </div>
                        <div className="space-y-2">
                          <label className="text-sm font-bold text-gray-700">Case Description</label>
                          <textarea required rows={5} className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-primary outline-none transition-all" placeholder="Explain what happened..." value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})}></textarea>
                        </div>
                      </div>
                    )}

                    {step === 3 && (
                      <div className="space-y-6 animate-in fade-in slide-in-from-right duration-300">
                        <div className="bg-blue-50 border border-blue-200 p-6 rounded-2xl">
                          <h4 className="font-bold text-primary mb-2 flex items-center"><ShieldQuestion size={16} className="mr-2" /> Verification & Support</h4>
                          <p className="text-sm text-blue-700 leading-relaxed mb-4">To help us assess your eligibility for pro-bono aid, please certify your status and upload supporting documents.</p>
                          <label className="flex items-center space-x-3 cursor-pointer group">
                            <input type="checkbox" className="w-5 h-5 rounded border-blue-400 text-primary focus:ring-primary" checked={formData.isIndigent} onChange={(e) => setFormData({...formData, isIndigent: e.target.checked})} />
