                            >
                              <FileUp size={40} className="mx-auto text-gray-300 group-hover:text-primary mb-3 transition-colors" />
                              <p className="text-sm font-bold text-gray-500 group-hover:text-primary">Click to select files</p>
                              <p className="text-[10px] text-gray-400 mt-1 uppercase tracking-wider">PDF, JPG, PNG, DOC (MAX 5MB)</p>
