                                      </div>
                                      <div className="overflow-hidden">
                                        <p className="text-sm font-bold text-gray-800 truncate">{f.file.name}</p>
                                        <p className="text-[10px] text-gray-500 uppercase">{(f.file.size / 1024).toFixed(1)} KB</p>
                                      </div>
                                    </div>
                                    <button onClick={() => removeFile(f.id)} className="text-gray-400 hover:text-red-500 transition-colors p-1">
                                      <X size={18} />
                                    </button>
                                  </div>

                                  {f.error ? (
                                    <div className="flex items-center text-red-600 text-[10px] font-bold">
                                      <AlertCircle size={12} className="mr-1" /> {f.error}
                                    </div>
                                  ) : (
                                    <div className="relative pt-1">
                                      <div className="flex mb-2 items-center justify-between">
                                        <div className="text-[10px] font-bold text-primary flex items-center">
                                          {f.progress < 100 ? (
                                            <><Loader2 size={10} className="animate-spin mr-1" /> Uploading...</>
                                          ) : (
                                            <><CheckCircle size={10} className="text-green-500 mr-1" /> Ready</>
                                          )}
                                        </div>
                                        <div className="text-right">
                                          <span className="text-[10px] font-bold text-gray-400">{f.progress}%</span>
                                        </div>
                                      </div>
                                      <div className="overflow-hidden h-1 text-xs flex rounded bg-gray-100">
                                        <div style={{ width: `${f.progress}%` }} className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-primary transition-all duration-300"></div>
                                      </div>
                                    </div>
                                  )}
                                </div>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    )}

                    <div className="flex items-center justify-between pt-6 border-t border-gray-100">
                      {step > 1 ? (
                        <button type="button" onClick={() => setStep(step - 1)} className="flex items-center font-bold text-gray-500 hover:text-primary px-6 py-3 transition-colors">
                          <ArrowLeft size={18} className="mr-2" /> Back
                        </button>
