                      >
                        {step === 3 ? (
                          <>Finish & Submit <Send size={18} className="ml-2" /></>
                        ) : (
                          <>Continue <ArrowRight size={18} className="ml-2" /></>
                        )}
                      </button>
                    </div>
                  </form>
                </div>
              ) : (
                <div className="bg-white rounded-3xl p-12 text-center border border-gray-100 shadow-xl animate-in zoom-in duration-500">
                  <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
                    <CheckCircle size={56} />
                  </div>
                  <h2 className="text-3xl font-bold text-gray-900 mb-4 font-serif">Application Received</h2>
                  <p className="text-gray-600 text-lg mb-8 max-w-md mx-auto">
                    Your case tracking reference is <span className="font-mono font-bold text-primary bg-blue-50 px-3 py-1 rounded">#UCLF-2024-8192</span>. 
                    A paralegal will review your application and conduct an assessment within 48 hours.
                  </p>
                  <div className="bg-gray-50 rounded-2xl p-6 mb-10 text-left border border-gray-100">
                    <h4 className="font-bold text-sm uppercase tracking-wider text-gray-400 mb-4">Next Steps</h4>
