                      <li className="flex items-start"><div className="w-3.5 h-3.5 rounded-full border-2 border-gray-300 mr-2 mt-0.5" /> Assignment of advocate or mediator.</li>
                    </ul>
                  </div>
                  <button onClick={() => { setSubmitted(false); setStep(1); setFiles([]); }} className="bg-primary text-white px-12 py-4 rounded-xl font-bold hover:bg-blue-800 transition-all shadow-lg">
                    Submit Another Application
                  </button>
                </div>
              )}
            </div>

            <div className="space-y-8">
              <div className="bg-white rounded-3xl p-8 border border-gray-200 shadow-sm">
                <h3 className="text-xl font-bold mb-4 flex items-center text-primary font-serif"><Search className="mr-2" /> Track Your Case</h3>
