    if (e.target.files) {
      const newFiles = Array.from(e.target.files).map((f: File) => {
        const id = Math.random().toString(36).substring(7);
        let error = "";
        if (f.size > 5 * 1024 * 1024) error = "File too large (>5MB)";
        const allowedTypes = ['application/pdf', 'image/jpeg', 'image/png', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
        if (!allowedTypes.includes(f.type)) error = "Unsupported format (Use PDF, JPG, PNG, or DOC)";

        return { id, file: f, progress: error ? 0 : 0, error };
      });

      setFiles(prev => [...prev, ...newFiles]);

      newFiles.forEach((nf) => {
        if (!nf.error) {
          let p = 0;
          const interval = setInterval(() => {
            p += Math.floor(Math.random() * 30) + 10;
            if (p >= 100) {
              p = 100;
              clearInterval(interval);
            }
            setFiles(current => 
              current.map(item => item.id === nf.id ? { ...item, progress: p } : item)
            );
          }, 400);
        }
      });
    }
  };

  const removeFile = (id: string) => {
    setFiles(prev => prev.filter(f => f.id !== id));
  };

