                  <div className="flex items-center text-xs font-semibold"><CheckCircle size={14} className="mr-2 text-secondary" /> Bail Applications</div>
                  <div className="flex items-center text-xs font-semibold"><CheckCircle size={14} className="mr-2 text-secondary" /> Bond Assistance</div>
                  <div className="flex items-center text-xs font-semibold"><CheckCircle size={14} className="mr-2 text-secondary" /> Family-Surety Linking</div>
