                    </div>
                  </div>
                  <button 
                    onClick={handleCloseModal}
                    className="bg-primary text-white px-12 py-3 rounded-xl font-bold shadow-lg"
                  >
                    Close
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

