                      <p>An invoice for the annual membership fee of <strong>{tiers.find(t => t.name === selectedTier)?.price}</strong> will be sent to your email.</p>
                    </div>
                    <div className="flex items-start space-x-4 text-sm text-gray-600">
                      <div className="w-6 h-6 rounded-full bg-primary/10 text-primary flex items-center justify-center shrink-0 mt-0.5 text-xs font-bold">3</div>
