                  </div>
                  <button 
                    onClick={handleCloseModal}
                    className="bg-primary text-white px-16 py-4 rounded-2xl font-bold shadow-xl hover:bg-blue-800 transition-all"
                  >
                    Finish
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

