                          <span className="text-xs font-bold text-gray-700">{trackingResult.submissionDate}</span>
                        </div>
                      </div>

                      <div className="space-y-4">
                        <div className="flex items-start space-x-3">
                          <div className="bg-blue-50 p-2 rounded-lg"><User size={14} className="text-primary" /></div>
                          <div>
                            <p className="text-[10px] text-gray-400 font-bold uppercase">Applicant</p>
                            <p className="text-sm font-bold text-gray-900">{trackingResult.requesterName}</p>
