                        </div>
                      </div>

                      <div className="mt-6 pt-6 border-t border-gray-200">
                        <button className="text-primary text-xs font-bold flex items-center hover:underline">
                          View Detailed Timeline <ExternalLink size={12} className="ml-1" />
