                      </div>
                    </div>
                  </div>
                )}

                {trackingResult === 'not-found' && (
                  <div className="mt-6 p-4 bg-red-50 rounded-xl border border-red-100 text-center animate-in shake duration-300">
                    <p className="text-xs font-bold text-red-600 flex items-center justify-center">
                      <AlertCircle size={14} className="mr-2" /> Reference number not found.
                    </p>
                  </div>
                )}
              </div>

              <div className="bg-primary text-white rounded-3xl p-8 shadow-xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                  <ShieldAlert size={80} />
                </div>
                <h3 className="text-xl font-bold mb-4 font-serif">Police & Prison Access</h3>
                <p className="text-sm text-blue-100 mb-6 leading-relaxed">Authorized by the Uganda Police Force and Prisons Service to access all units for legal education and counseling.</p>
                <div className="space-y-3">
                  <div className="flex items-center text-xs font-semibold"><CheckCircle size={14} className="mr-2 text-secondary" /> Bail Applications</div>
                  <div className="flex items-center text-xs font-semibold"><CheckCircle size={14} className="mr-2 text-secondary" /> Bond Assistance</div>
                  <div className="flex items-center text-xs font-semibold"><CheckCircle size={14} className="mr-2 text-secondary" /> Family-Surety Linking</div>
                  <div className="flex items-center text-xs font-semibold"><CheckCircle size={14} className="mr-2 text-secondary" /> Self-Representation Training</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="py-16 bg-white border-t border-gray-100">
        <div className="max-w-4xl mx-auto px-4">
          <div className="bg-gray-50 p-8 rounded-3xl border border-dashed border-gray-300">
            <h4 className="font-bold text-gray-900 mb-4 flex items-center font-serif">
              <ShieldQuestion className="text-primary mr-2" /> Important Disclaimer
            </h4>
            <p className="text-sm text-gray-600 leading-relaxed italic">
              Legal information provided on this platform does not constitute legal advice. UCLF represents indigent clients who meet our vulnerability criteria. Submission of a case does not automatically create an advocate-client relationship until a formal assessment and assignment is completed.
            </p>
          </div>
        </div>
      </section>
    </div>
  );
};

