import React, { useState, useRef } from 'react';
import { Check, UserPlus, Briefcase, GraduationCap, Award, BookOpen, Star, X, Upload, FileText, CheckCircle, Loader2, AlertCircle, ArrowRight, Building2, Landmark, ShieldCheck } from 'lucide-react';
import { MembershipTier } from '../types';

interface BaseForm {
  name: string;
  email: string;
  phone: string;
  cv: File | null;
  church: string;
}

interface StudentForm extends BaseForm {
  university: string;
  faculty: string;
  yearOfStudy: string;
  studentId: string;
  gradYear: string;
}

interface FullMemberForm extends BaseForm {
  barNumber: string;
  rollNumber: string;
  firmName: string;
  practiceYears: string;
  specialization: string;
  proBonoInterest: boolean;
}

interface AssociateForm extends BaseForm {
  profession: string;
  employer: string;
  designation: string;
  reasonForJoining: string;
  otherMemberships: string;
}

type MembershipFormState = StudentForm & FullMemberForm & AssociateForm;

