  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTier, setSelectedTier] = useState<MembershipTier | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const [formData, setFormData] = useState<Partial<MembershipFormState>>({
    name: '',
    email: '',
    phone: '',
    cv: null,
    church: '',
    university: '',
    faculty: '',
    yearOfStudy: '',
    studentId: '',
    gradYear: '',
    barNumber: '',
    rollNumber: '',
    firmName: '',
    practiceYears: '',
    specialization: '',
    proBonoInterest: false,
    profession: '',
    employer: '',
    designation: '',
    reasonForJoining: '',
    otherMemberships: '',
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const tiers = [
    {
      name: MembershipTier.STUDENT,
      icon: <GraduationCap size={32} />,
      price: '50,000 UGX',
      period: 'per year',
      features: ['University Chapters', 'Annual Law Symposium', 'Internship Placement', 'Leadership Retreats', 'Spiritual Mentorship'],
      color: 'bg-gray-100',
    },
    {
      name: MembershipTier.FULL,
      icon: <Briefcase size={32} />,
      price: '200,000 UGX',
      period: 'per year',
      features: ['Voting Rights', 'Licensed CLE Credits', 'Bar & Bench Events', 'UCLF Law Journal Access', 'Pro Bono Assignments'],
      color: 'bg-blue-50 border-2 border-primary',
      popular: true,
    },
    {
      name: MembershipTier.ASSOCIATE,
      icon: <Award size={32} />,
      price: '150,000 UGX',
      period: 'per year',
      features: ['Networking Opportunities', 'Faith & Ethics Seminars', 'Small Group Fellowship', 'Welfare Support', 'Access to Events'],
      color: 'bg-gray-100',
    },
  ];

  const handleOpenModal = (tier: MembershipTier) => {
    setSelectedTier(tier);
    setIsModalOpen(true);
    setIsSubmitted(false);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setFormData({
      name: '', email: '', phone: '', cv: null, church: '',
      university: '', faculty: '', yearOfStudy: '', studentId: '', gradYear: '',
      barNumber: '', rollNumber: '', firmName: '', practiceYears: '', specialization: '', proBonoInterest: false,
      profession: '', employer: '', designation: '', reasonForJoining: '', otherMemberships: '',
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFormData({ ...formData, cv: e.target.files[0] });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSubmitted(true);
