                        className="hidden" 
                        onChange={handleFileChange}
                        accept=".pdf,.doc,.docx"
                      />
                      {formData.cv ? (
                        <div className="flex flex-col items-center text-primary animate-in zoom-in duration-300">
                          <div className="w-16 h-16 bg-blue-100 rounded-2xl flex items-center justify-center mb-4 text-primary shadow-sm">
                             <FileText size={32} />
