                          <p className="text-[10px] uppercase mt-1">{(formData.cv.size / 1024).toFixed(1)} KB uploaded successfully</p>
                          <button 
                            type="button" 
                            onClick={(e) => { e.stopPropagation(); setFormData({...formData, cv: null}); }}
                            className="mt-4 text-xs font-bold text-red-500 hover:underline"
                          >
                            Remove and Replace
                          </button>
                        </div>
                      ) : (
                        <div className="text-gray-400">
                          <Upload className="mx-auto mb-4 opacity-50" size={48} />
                          <p className="text-base font-bold text-gray-700">Upload Your Professional CV / Bio</p>
                          <p className="text-xs mt-1">Accepts PDF, DOCX (Max 10MB)</p>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Declaration */}
                  <div className="p-8 bg-gray-900 text-white rounded-3xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-10">
                      <ShieldCheck size={120} />
                    </div>
                    <div className="relative z-10">
                      <h4 className="text-lg font-bold mb-4 font-serif text-secondary">Membership Declaration</h4>
                      <p className="text-xs text-blue-100 leading-relaxed mb-6">
                        "I hereby solemnly declare my commitment to the <strong>Uganda Christian Lawyers Fraternity (UCLF)</strong>. 
                        I pledge to uphold the <strong>Code of Christian Legal Ethics</strong>, to serve the indigent with compassion, and to maintain 
                        highest standards of professional excellence in accordance with Biblical principles and the Laws of Uganda."
                      </p>
                      <div className="flex items-center space-x-3">
                        <input required type="checkbox" className="w-5 h-5 rounded border-gray-600 text-secondary focus:ring-secondary bg-gray-800" id="agree" />
                        <label htmlFor="agree" className="text-xs font-bold text-white uppercase tracking-wider">I Accept and Agree to the above declaration.</label>
                      </div>
                    </div>
                  </div>

                  <div className="pt-4 sticky bottom-0 bg-white pb-8">
                    <button 
                      type="submit" 
                      disabled={isSubmitting}
                      className="w-full bg-primary text-white py-5 rounded-2xl font-bold flex items-center justify-center hover:bg-blue-800 transition-all shadow-xl disabled:opacity-50"
                    >
                      {isSubmitting ? (
                        <><Loader2 className="animate-spin mr-2" size={24} /> Validating Credentials...</>
                      ) : (
                        <>Submit Final Application <ArrowRight className="ml-2" size={24} /></>
                      )}
                    </button>
                  </div>
                </form>
              ) : (
                <div className="py-20 text-center animate-in zoom-in duration-500">
                  <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
                    <CheckCircle size={56} />
                  </div>
                  <h3 className="text-3xl font-bold text-gray-900 mb-4 font-serif">Submission Successful</h3>
                  <p className="text-gray-600 text-lg mb-8 max-w-md mx-auto">
                    Thank you, <span className="font-bold text-primary">{formData.name}</span>. Your {selectedTier} membership application has been logged into our system.
                  </p>
                  <div className="bg-gray-50 rounded-3xl p-10 border border-gray-100 text-left space-y-6 mb-10 max-w-2xl mx-auto">
                    <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest border-b pb-4">Onboarding Roadmap</h4>
                    <div className="flex items-start space-x-4">
                      <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center shrink-0 mt-0.5 text-xs font-bold">01</div>
                      <div>
                         <h5 className="font-bold text-gray-900 text-sm">Committee Review</h5>
                         <p className="text-xs text-gray-500">Your documents will be reviewed by the Membership & Ethics Committee (3-5 business days).</p>
                      </div>
                    </div>
                    <div className="flex items-start space-x-4">
                      <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center shrink-0 mt-0.5 text-xs font-bold">02</div>
                      <div>
                         <h5 className="font-bold text-gray-900 text-sm">Fee Assessment</h5>
                         <p className="text-xs text-gray-500">Upon approval, you will receive an official invoice for the {tiers.find(t => t.name === selectedTier)?.price} annual fee.</p>
                      </div>
                    </div>
                    <div className="flex items-start space-x-4">
                      <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center shrink-0 mt-0.5 text-xs font-bold">03</div>
                      <div>
                         <h5 className="font-bold text-gray-900 text-sm">Induction</h5>
                         <p className="text-xs text-gray-500">You'll be added to the official UCLF Registry and receive your digital membership ID.</p>
                      </div>
                    </div>
                  </div>
                  <button 
                    onClick={handleCloseModal}
                    className="bg-primary text-white px-20 py-4 rounded-2xl font-bold shadow-xl hover:bg-blue-800 transition-all"
                  >
                    Return to Membership
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Membership;

export enum MembershipTier {
  STUDENT = 'Student',
  ASSOCIATE = 'Associate',
  FULL = 'Full Member'
}

export enum MembershipStatus {
  ACTIVE = 'Active',
  INACTIVE = 'Inactive',
  PENDING = 'Pending'
}

export enum CaseStatus {
  PENDING = 'Pending',
  ASSIGNED = 'Assigned',
  IN_PROGRESS = 'In Progress',
  RESOLVED = 'Resolved',
  CLOSED = 'Closed'
}

export enum UrgencyLevel {
  LOW = 'Low',
  MEDIUM = 'Medium',
  HIGH = 'High'
}

export interface RegionalOffice {
  name: string;
  districts: string[];
  presence: string;
}

export interface Member {
  id: string;
  fullName: string;
  email: string;
  barCouncilNumber: string;
  phone: string;
  tier: MembershipTier;
  status: MembershipStatus;
  specialization: string;
  yearsOfPractice: number;
}

export interface LegalAidRequest {
  id: string;
  caseRef: string;
  requesterName: string;
  requesterContact: string;
  description: string;
  urgency: UrgencyLevel;
  status: CaseStatus;
  submissionDate: string;
}

export interface Event {
  id: string;
  title: string;
  description: string;
  type: 'Fellowship' | 'CLE' | 'Workshop' | 'Conference';
  date: string;
  location: string;
  cleCredits?: number;
}

export interface Resource {
  id: string;
  title: string;
  category: string;
  type: 'PDF' | 'DOC' | 'Link' | 'Audio' | 'Video' | 'Case';
  date: string;
  url?: string;
}

