}

const AIAssistant: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'assistant', 
      text: "Welcome to the UCLF AI Legal Assistant. I am an expert on the Ugandan legal system, specializing in constitutional law, statutes, and case precedents. You can ask me questions about Ugandan law or upload contracts and documents for my analysis. How can I assist you today?" 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [attachment, setAttachment] = useState<{ file: File; base64: string } | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        alert("File too large. Maximum size is 5MB.");
        return;
      }

      const reader = new FileReader();
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        setAttachment({ file, base64 });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() && !attachment) return;

    const userMessage: Message = { 
      role: 'user', 
      text: input,
      attachment: attachment ? {
        name: attachment.file.name,
        type: attachment.file.type,
        data: attachment.base64
      } : undefined
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    const currentAttachment = attachment;
    setAttachment(null);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const parts: any[] = [{ text: input || "Please analyze this document." }];

      if (currentAttachment) {
        parts.push({
          inlineData: {
            mimeType: currentAttachment.file.type,
            data: currentAttachment.base64
          }
        });
      }

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: { parts },
        config: {
          systemInstruction: `You are the UCLF AI Legal Assistant, a premier legal expert in the Republic of Uganda. 
          Your knowledge base includes:
          1. The Constitution of the Republic of Uganda.
          2. All major statutes and Acts of Parliament (Evidence Act, Penal Code, Land Act, etc.).
          3. Precedents from the Supreme Court, Court of Appeal, and High Court of Uganda.
          4. Christian legal ethics as promoted by the Uganda Christian Lawyers Fraternity.

          Your capabilities:
          - Summarize Ugandan legal concepts.
          - Analyze contracts and documents for potential issues under Ugandan law.
          - Cite specific Ugandan statutes or cases where applicable.
          - Provide guidance on court procedures in Uganda.

          Style:
          - Professional, precise, and authoritative.
          - Maintain a helpful, Christian perspective on justice and dignity.

          Mandatory Disclaimer:
          - Always mention that you are an AI assistant and your responses are for educational and preliminary guidance only, not professional legal advice from an advocate-client relationship.`,
        }
      });

      const aiText = response.text || "I'm sorry, I encountered an error processing that request. Please try again.";
      setMessages(prev => [...prev, { role: 'assistant', text: aiText }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'assistant', text: "I apologize, but I am having trouble connecting to my legal database at the moment. Please check your internet connection and try again." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="bg-gray-50 min-h-[calc(100-80px)] flex flex-col">
      {/* Header */}
      <div className="bg-white border-b border-gray-100 px-4 py-4 sticky top-0 z-20">
        <div className="max-w-5xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <Link to="/resources" className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-500">
              <ArrowLeft size={20} />
            </Link>
            <div className="flex items-center space-x-3">
              <div className="bg-primary p-2.5 rounded-2xl text-secondary shadow-lg">
                <Sparkles size={24} />
              </div>
              <div>
                <h1 className="text-xl font-bold text-gray-900 font-serif">Legal AI Assistant</h1>
                <div className="flex items-center text-[10px] text-green-500 font-bold uppercase tracking-widest">
                  <div className="w-1.5 h-1.5 bg-green-500 rounded-full mr-1.5 animate-pulse"></div>
                  Ugandan Law Expert Online
                </div>
              </div>
            </div>
          </div>
          <div className="hidden md:flex items-center space-x-2 bg-blue-50 px-4 py-2 rounded-xl border border-blue-100">
            <ShieldCheck size={16} className="text-primary" />
            <span className="text-[10px] font-bold text-primary uppercase tracking-widest">Confidential & Secure</span>
          </div>
        </div>
      </div>

      {/* Disclaimer Bar */}
      <div className="bg-yellow-50 border-b border-yellow-100 py-2 px-4 text-center">
        <p className="text-[10px] font-bold text-yellow-800 uppercase tracking-widest flex items-center justify-center">
          <AlertCircle size={12} className="mr-2" /> AI Education Tool - Not Professional Legal Advice
        </p>
      </div>

      {/* Chat Area */}
      <div className="flex-grow overflow-y-auto px-4 py-8">
        <div className="max-w-4xl mx-auto space-y-8">
          {messages.map((m, idx) => (
            <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`flex max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-start`}>
                <div className={`shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center shadow-md ${
                  m.role === 'user' ? 'bg-secondary text-primary ml-4' : 'bg-primary text-secondary mr-4'
                }`}>
                  {m.role === 'user' ? <User size={20} /> : <Sparkles size={20} />}
                </div>
                <div className={`rounded-3xl p-6 shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-primary text-white rounded-tr-none' 
                  : 'bg-white border border-gray-100 text-gray-800 rounded-tl-none'
                }`}>
                  {m.attachment && (
                    <div className={`mb-4 p-4 rounded-2xl flex items-center space-x-3 ${m.role === 'user' ? 'bg-white/10' : 'bg-gray-50'}`}>
                      <FileText size={20} className={m.role === 'user' ? 'text-secondary' : 'text-primary'} />
                      <div className="text-left">
                        <p className="text-xs font-bold truncate max-w-[200px]">{m.attachment.name}</p>
                        <p className="text-[10px] uppercase opacity-60">Uploaded Document</p>
                      </div>
                    </div>
                  )}
                  <div className="prose prose-sm prose-blue max-w-none whitespace-pre-wrap leading-relaxed">
                    {m.text}
                  </div>
                </div>
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex justify-start">
              <div className="flex items-start">
                <div className="shrink-0 w-10 h-10 rounded-2xl bg-primary text-secondary mr-4 flex items-center justify-center shadow-md">
                  <Sparkles size={20} className="animate-spin duration-1000" />
                </div>
                <div className="bg-white border border-gray-100 p-6 rounded-3xl rounded-tl-none shadow-sm flex items-center space-x-2">
                  <Loader2 size={16} className="animate-spin text-primary" />
                  <span className="text-sm font-bold text-gray-400 uppercase tracking-widest">Consulting Legal Database...</span>
                </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-gray-100 p-4 lg:p-6 sticky bottom-0">
        <div className="max-w-4xl mx-auto">
          {attachment && (
            <div className="mb-4 p-3 bg-blue-50 rounded-2xl border border-blue-100 flex items-center justify-between animate-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center space-x-3">
                <FileText className="text-primary" size={20} />
                <span className="text-sm font-bold text-primary truncate max-w-[250px]">{attachment.file.name}</span>
              </div>
              <button onClick={() => setAttachment(null)} className="p-1 hover:bg-white rounded-full transition-colors text-primary">
                <X size={18} />
              </button>
            </div>
          )}

          <form onSubmit={handleSend} className="relative flex items-center space-x-4">
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="p-4 bg-gray-50 text-gray-400 hover:text-primary hover:bg-blue-50 rounded-2xl transition-all border border-gray-100 shadow-sm shrink-0"
              title="Upload legal document"
            >
              <Upload size={24} />
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              onChange={handleFileUpload}
              accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.txt"
            />

            <div className="relative flex-grow">
              <textarea 
                rows={1}
                className="w-full px-6 py-4 rounded-3xl border border-gray-200 focus:ring-4 focus:ring-primary/10 focus:border-primary outline-none transition-all pr-16 bg-gray-50/50 resize-none font-medium"
                placeholder="Ask a question about Ugandan law..."
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleSend();
                  }
                }}
              />
              <button 
                type="submit"
                disabled={isTyping || (!input.trim() && !attachment)}
                className="absolute right-3 top-2 p-2 bg-primary text-white rounded-2xl hover:bg-blue-800 transition-all shadow-lg disabled:opacity-50 disabled:bg-gray-300"
              >
                <Send size={24} />
              </button>
            </div>
          </form>

          <div className="mt-4 flex items-center justify-center space-x-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
            <div className="flex items-center"><Info size={12} className="mr-1.5" /> Constitutional Law</div>
            <div className="flex items-center"><Info size={12} className="mr-1.5" /> Contract Review</div>
            <div className="flex items-center"><Info size={12} className="mr-1.5" /> Case Citations</div>
          </div>
        </div>
      </div>
    </div>
  );
};

