import React, { useState, useEffect } from 'react';
import { Menu, X, Gavel, User, Heart, BookOpen, Calendar, Info, PhoneCall, Briefcase, LayoutDashboard, GraduationCap } from 'lucide-react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { MembershipTier } from '../types';

interface UserSession {
  name: string;
  tier: MembershipTier;
}

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const [user, setUser] = useState<UserSession | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('uclf_user');
    if (saved) {
      try {
        setUser(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse user session", e);
      }
    }
  }, [location.pathname]); // Refresh on navigation

  const navLinks = [
    { name: 'Home', path: '/', icon: <Gavel size={18} /> },
    { name: 'About', path: '/about', icon: <Info size={18} /> },
    { name: 'Membership', path: '/membership', icon: <User size={18} /> },
    { name: 'Legal Aid', path: '/legal-aid', icon: <Gavel size={18} /> },
    { name: 'Events', path: '/events', icon: <Calendar size={18} /> },
    { name: 'Resources', path: '/resources', icon: <BookOpen size={18} /> },
    { name: 'Donate', path: '/donate', icon: <Heart size={18} /> },
  ];

  const getDashboardLink = () => {
    if (!user) return null;
    if (user.tier === MembershipTier.FULL) {
      return { path: '/case-management', label: 'Advocate Dashboard', icon: <Briefcase size={16} /> };
    }
    if (user.tier === MembershipTier.ASSOCIATE) {
      return { path: '/associate-dashboard', label: 'Associate Dashboard', icon: <LayoutDashboard size={16} /> };
    }
    if (user.tier === MembershipTier.STUDENT) {
      return { path: '/student-dashboard', label: 'Student Hub', icon: <GraduationCap size={16} /> };
    }
    return null;
  };

  const dashboard = getDashboardLink();

  const handleLogout = () => {
    localStorage.removeItem('uclf_user');
    setUser(null);
    navigate('/');
  };

  return (
    <nav className="bg-white shadow-md sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20">
          <div className="flex items-center">
            <Link to="/" className="flex items-center space-x-2">
              <div className="bg-primary p-2 rounded-lg">
                <Gavel className="text-white" size={24} />
              </div>
              <div>
                <span className="text-xl font-bold text-primary block leading-tight">UCLF</span>
                <span className="text-[10px] uppercase tracking-wider text-gray-500 font-semibold">Uganda Christian Lawyers</span>
              </div>
            </Link>
          </div>

          {/* Desktop Nav */}
          <div className="hidden lg:flex items-center space-x-4">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`flex items-center space-x-1 px-3 py-2 rounded-md text-[13px] font-bold transition-colors ${
                  location.pathname === link.path
                    ? 'text-primary bg-blue-50'
                    : 'text-gray-600 hover:text-primary hover:bg-gray-50'
                }`}
              >
                {link.name}
              </Link>
            ))}

            {dashboard && (
              <Link
                to={dashboard.path}
                className="flex items-center space-x-2 bg-blue-50 text-primary px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest border border-primary/20 hover:bg-blue-100 transition-all ml-2"
              >
                {dashboard.icon}
                <span>{dashboard.label}</span>
              </Link>
            )}

            {!user ? (
              <Link
                to="/login"
                className="ml-4 bg-primary text-white px-5 py-2.5 rounded-lg text-sm font-semibold hover:bg-blue-800 transition-all shadow-sm"
              >
                Member Login
              </Link>
            ) : (
              <div className="flex items-center ml-4 space-x-4">
                 <div className="flex items-center space-x-3">
                   <div className="w-8 h-8 rounded-full bg-primary text-secondary flex items-center justify-center font-black text-xs border border-primary/10">
                      {user.name.charAt(0)}
                   </div>
                   <span className="text-xs font-bold text-gray-500 hidden xl:block">{user.name.split(' ')[0]}</span>
                 </div>
                 <button 
                  onClick={handleLogout}
                  className="text-gray-400 hover:text-red-500 transition-colors p-1"
                  title="Logout"
                 >
                   <LogOut size={18} />
                 </button>
              </div>
            )}
          </div>

          {/* Mobile menu button */}
          <div className="lg:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-gray-600 hover:text-primary p-2"
            >
              {isOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Nav */}
      {isOpen && (
        <div className="lg:hidden bg-white border-t border-gray-100 animate-in slide-in-from-top duration-300">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`flex items-center space-x-3 block px-3 py-4 rounded-md text-base font-medium ${
                  location.pathname === link.path
                    ? 'text-primary bg-blue-50'
                    : 'text-gray-600 hover:text-primary hover:bg-gray-50'
                }`}
              >
                {link.icon}
                <span>{link.name}</span>
              </Link>
            ))}

            {dashboard && (
              <Link
                to={dashboard.path}
                onClick={() => setIsOpen(false)}
                className="flex items-center space-x-3 px-3 py-4 text-primary bg-blue-50 rounded-md text-base font-bold"
              >
                {dashboard.icon}
                <span>{dashboard.label}</span>
              </Link>
            )}

            {!user ? (
              <Link
                to="/login"
                onClick={() => setIsOpen(false)}
                className="flex items-center justify-center space-x-2 w-full mt-4 bg-primary text-white px-3 py-3 rounded-md text-base font-medium shadow-md"
              >
                <User size={18} />
                <span>Member Login</span>
              </Link>
            ) : (
              <button
                onClick={() => { handleLogout(); setIsOpen(false); }}
                className="flex items-center space-x-3 px-3 py-4 text-red-500 hover:bg-red-50 rounded-md text-base font-bold w-full text-left"
              >
                <LogOut size={20} />
                <span>Sign Out</span>
              </button>
            )}
          </div>
        </div>
      )}
    </nav>
  );
};

const LogOut = ({ size, className }: { size?: number, className?: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/>
  </svg>
);

export default Navbar;

