const EventsNews: React.FC = () => {
  const navigate = useNavigate();
  const [events, setEvents] = useState<Event[]>(INITIAL_EVENTS);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [rsvpLoading, setRsvpLoading] = useState<string | null>(null);

  // Calendar State
  const [currentMonth, setCurrentMonth] = useState(new Date(2024, 3, 1)); // Default to April 2024
  const [selectedDay, setSelectedDay] = useState<number | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('uclf_user');
    if (saved) {
      try {
        setCurrentUser(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse user session", e);
      }
    }
  }, []);

  const handleRSVP = (eventId: string) => {
    if (!currentUser) {
      navigate('/login');
      return;
    }

    setRsvpLoading(eventId);

    // Simulate API call to register/unregister for the event
    setTimeout(() => {
      setEvents(prev => prev.map(event => {
        if (event.id === eventId) {
          const isRemoving = event.isRSVPed;
          return {
            ...event,
            isRSVPed: !isRemoving,
            filled: isRemoving ? event.filled - 1 : event.filled + 1
          };
        }
        return event;
      }));
      setRsvpLoading(null);
    }, 1200);
  };

  // Calendar Helpers
  const daysInMonth = (month: number, year: number) => new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = (month: number, year: number) => new Date(year, month, 1).getDay();

  const calendarDays = useMemo(() => {
    const month = currentMonth.getMonth();
    const year = currentMonth.getFullYear();
    const totalDays = daysInMonth(month, year);
    const firstDay = firstDayOfMonth(month, year);

    const days = [];
    // Fill padding
    for (let i = 0; i < firstDay; i++) {
      days.push(null);
    }
    // Fill days
    for (let i = 1; i <= totalDays; i++) {
      days.push(i);
    }
    return days;
  }, [currentMonth]);

  const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

  const changeMonth = (offset: number) => {
    setCurrentMonth(prev => new Date(prev.getFullYear(), prev.getMonth() + offset, 1));
    setSelectedDay(null);
  };

  // Filter events based on selected calendar date
  const filteredEvents = useMemo(() => {
    if (selectedDay === null) return events;

    return events.filter(e => {
      // Parse event date like "April 15, 2024"
      const datePart = e.date.split(' • ')[0];
      const eventDateObj = new Date(datePart);

      return (
        eventDateObj.getDate() === selectedDay &&
        eventDateObj.getMonth() === currentMonth.getMonth() &&
        eventDateObj.getFullYear() === currentMonth.getFullYear()
      );
    });
  }, [events, selectedDay, currentMonth]);

  // Check if a day has an event for calendar indicators
  const hasEventOnDay = (day: number) => {
    return events.some(e => {
      const datePart = e.date.split(' • ')[0];
      const eventDateObj = new Date(datePart);
      return (
        eventDateObj.getDate() === day &&
        eventDateObj.getMonth() === currentMonth.getMonth() &&
        eventDateObj.getFullYear() === currentMonth.getFullYear()
      );
    });
  };

  return (
    <div className="bg-gray-50 min-h-screen">
      {/* Header */}
      <div className="bg-primary py-24 px-4 text-center relative overflow-hidden">
        <div className="absolute inset-0 opacity-10">
          <img src="https://images.unsplash.com/photo-1505664194779-8beaceb93744?auto=format&fit=crop&q=80" alt="background" className="w-full h-full object-cover" />
        </div>
        <div className="max-w-4xl mx-auto relative z-10">
          <h1 className="text-5xl lg:text-7xl font-bold text-white mb-6 font-serif tracking-tight">Events & News</h1>
          <p className="text-xl text-blue-100 italic max-w-2xl mx-auto font-medium">
            Stay updated with our latest activities, professional seminars, and fellowship gatherings across the Republic.
          </p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-16">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

          {/* Main Events Section */}
          <div className="lg:col-span-8 space-y-12">

