                            <div className="flex items-center space-x-2">
                               <span className="text-[11px] font-black uppercase tracking-widest text-gray-400">Venue Capacity</span>
                               {isUrgent && (
                                 <span className="flex items-center text-[10px] font-black text-orange-600 uppercase animate-pulse">
                                   <AlertTriangle size={12} className="mr-1" /> Filling Fast
                                 </span>
                               )}
                            </div>
                            <span className={`text-[11px] font-black uppercase tracking-widest ${isFull ? 'text-red-600' : 'text-primary'}`}>
                              {isFull ? 'Sold Out' : `${Math.round(capacityPercent)}% Filled`}
                            </span>
                          </div>
                          <div className="h-2.5 w-full bg-gray-100 rounded-full overflow-hidden shadow-inner">
                            <div 
                              className={`h-full transition-all duration-1000 ease-out ${
                                isFull ? 'bg-red-600' : capacityPercent > 80 ? 'bg-yellow-500' : 'bg-primary'
                              }`}
                              style={{ width: `${capacityPercent}%` }}
                            ></div>
                          </div>
                        </div>

                        {/* RSVP Action */}
                        <div className="flex flex-col sm:flex-row items-center justify-between pt-8 border-t border-gray-100 gap-6">
                          <button
                            onClick={() => handleRSVP(event.id)}
                            disabled={rsvpLoading === event.id || (isFull && !event.isRSVPed)}
                            className={`w-full sm:w-auto px-12 py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center shadow-xl transition-all active:scale-95 ${
                              event.isRSVPed 
                                ? 'bg-green-600 text-white hover:bg-red-600 hover:shadow-red-200 group/btn' 
                                : isFull 
                                  ? 'bg-gray-100 text-gray-400 cursor-not-allowed shadow-none'
                                  : 'bg-primary text-white hover:bg-blue-800 shadow-primary/20'
                            }`}
                          >
                            {rsvpLoading === event.id ? (
                              <Loader2 size={20} className="animate-spin mr-3" />
                            ) : event.isRSVPed ? (
                              <>
                                <CheckCircle size={20} className="mr-3 group-hover/btn:hidden" />
