import React, { useState, useEffect } from 'react';
import { 
  ShieldAlert, Image as ImageIcon, Handshake, Calendar, 
  Plus, Trash2, Save, LogOut, ChevronRight, LayoutDashboard,
  ExternalLink, CheckCircle, AlertTriangle, Users, Globe,
  Clock, FileText, Camera
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Event } from '../types';

const AdminDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'gallery' | 'partners' | 'events'>('gallery');

  // Gallery State
  const [gallery, setGallery] = useState<string[]>([]);
  const [newImageUrl, setNewImageUrl] = useState('');

  // Partners State
  const [partners, setPartners] = useState<{name: string, type: string}[]>([]);
  const [newPartner, setNewPartner] = useState({ name: '', type: '' });

  // Events State
  const [events, setEvents] = useState<Event[]>([]);
  const [newEvent, setNewEvent] = useState<Partial<Event>>({
    title: '',
    description: '',
    type: 'Fellowship',
    date: '',
    location: '',
    cleCredits: 0,
    capacity: 50,
    filled: 0
  });

  // Notifications
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => {
    // Check auth
    const userStr = localStorage.getItem('uclf_user');
    if (!userStr || JSON.parse(userStr).tier !== 'Admin') {
      navigate('/login');
      return;
    }

    // Load initial data
    const savedGallery = localStorage.getItem('uclf_gallery');
    if (savedGallery) setGallery(JSON.parse(savedGallery));

    const savedPartners = localStorage.getItem('uclf_partners');
    if (savedPartners) setPartners(JSON.parse(savedPartners));

    const savedEvents = localStorage.getItem('uclf_events');
    if (savedEvents) setEvents(JSON.parse(savedEvents));
  }, [navigate]);

  const showNotice = (msg: string, type: 'success' | 'error' = 'success') => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleLogout = () => {
    localStorage.removeItem('uclf_user');
    navigate('/login');
    window.location.reload();
  };

  // Gallery Handlers
  const addImage = () => {
    if (!newImageUrl.trim()) return;
    const updated = [...gallery, newImageUrl];
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    setNewImageUrl('');
    showNotice('Photo added to scrolling gallery');
  };

  const removeImage = (index: number) => {
    const updated = gallery.filter((_, i) => i !== index);
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    showNotice('Photo removed');
  };

  // Partner Handlers
  const addPartner = () => {
    if (!newPartner.name || !newPartner.type) return;
    const updated = [...partners, newPartner];
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    setNewPartner({ name: '', type: '' });
    showNotice('Strategic partner added');
  };

  const removePartner = (index: number) => {
    const updated = partners.filter((_, i) => i !== index);
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    showNotice('Partner removed');
  };

  // Event Handlers
  const addEvent = () => {
    if (!newEvent.title || !newEvent.date) return;
    const id = 'e' + Date.now();
    const updated = [...events, { ...newEvent, id } as Event];
    setEvents(updated);
    localStorage.setItem('uclf_events', JSON.stringify(updated));
    setNewEvent({
      title: '',
      description: '',
      type: 'Fellowship',
      date: '',
      location: '',
      cleCredits: 0,
      capacity: 50,
      filled: 0
    });
    showNotice('Event and calendar program added');
  };

  const removeEvent = (id: string) => {
    const updated = events.filter(e => e.id !== id);
