    setEvents(updated);
    localStorage.setItem('uclf_events', JSON.stringify(updated));
    setNewEvent({
      title: '',
      description: '',
      type: 'Fellowship',
      date: '',
      location: '',
      cleCredits: 0,
      capacity: 50,
      filled: 0
    });
    showNotice('Event and calendar program added');
  };

