                            className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                            placeholder="April 20, 2024 • 10:00 AM"
                            value={newEvent.date}
                            onChange={e => setNewEvent({...newEvent, date: e.target.value})}
                           />
                        </div>
                        <div>
                           <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Location</label>
                           <input 
                            type="text" 
                            className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                            placeholder="Venue name or Digital Link"
                            value={newEvent.location}
                            onChange={e => setNewEvent({...newEvent, location: e.target.value})}
                           />
                        </div>
                     </div>
                  </div>

                  <button 
                    onClick={addEvent}
                    className="w-full bg-red-600 text-white py-6 rounded-2xl font-black text-xs uppercase tracking-[0.2em] hover:bg-red-700 transition-all shadow-2xl shadow-red-900/20 active:scale-[0.98] flex items-center justify-center"
                  >
                    <Save size={20} className="mr-3" /> Commit to Public Feed & Calendar
                  </button>
               </div>

               <div className="space-y-6">
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4">Live Program Directory ({events.length})</h3>
                  <div className="space-y-4">
                     {events.map((e) => (
                        <div key={e.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:border-red-100 hover:shadow-xl transition-all">
                           <div className="flex items-center space-x-8">
                              <div className="w-16 h-16 bg-slate-900 rounded-2xl flex flex-col items-center justify-center text-white shadow-lg shadow-slate-900/20">
                                 <span className="text-[10px] font-black uppercase opacity-60 leading-none mb-1">{e.date.split(' ')[0]}</span>
                                 <span className="text-2xl font-black leading-none">{e.date.split(' ')[1]?.replace(',', '') || '??'}</span>
                              </div>
                              <div>
                                 <div className="flex items-center space-x-3 mb-2">
                                    <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${e.type === 'CLE' ? 'bg-purple-600 text-white' : 'bg-slate-100 text-slate-600'}`}>{e.type}</span>
                                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center"><MapPin size={10} className="mr-1" /> {e.location}</span>
                                 </div>
                                 <h4 className="text-lg font-black text-slate-900">{e.title}</h4>
                              </div>
                           </div>
                           <button 
                            onClick={() => removeEvent(e.id)}
                            className="bg-red-50 text-red-600 p-4 rounded-2xl hover:bg-red-600 hover:text-white transition-all opacity-0 group-hover:opacity-100 shadow-sm"
                           >
                              <Trash2 size={20} />
                           </button>
                        </div>
                     ))}
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;

