import React, { useState, useEffect } from 'react';
import { 
  ShieldAlert, Image as ImageIcon, Handshake, Calendar, 
  Plus, Trash2, Save, LogOut, ChevronRight, LayoutDashboard,
  ExternalLink, CheckCircle, AlertTriangle, Users, Globe,
  Clock, FileText, Camera, MapPin
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Event } from '../types';

const DEFAULT_GALLERY = [
  'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1521791136064-7986c2920216?auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1589829545856-d10d557cf95f?auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1505664194779-8beaceb93744?auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1423666639041-f56000c27a9a?auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?auto=format&fit=crop&q=80',
];

const AdminDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'gallery' | 'partners' | 'events'>('gallery');

  // Gallery State
  const [gallery, setGallery] = useState<string[]>([]);
  const [newImageUrl, setNewImageUrl] = useState('');

  // Partners State
  const [partners, setPartners] = useState<{name: string, type: string}[]>([]);
  const [newPartner, setNewPartner] = useState({ name: '', type: '' });

  // Events State
  const [events, setEvents] = useState<Event[]>([]);
  const [newEvent, setNewEvent] = useState<Partial<Event>>({
    title: '',
    description: '',
    type: 'Fellowship',
    date: '',
    location: '',
    cleCredits: 0,
    capacity: 50,
    filled: 0,
    imageUrl: ''
  });

  // Notifications
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => {
    // Check auth
    const userStr = localStorage.getItem('uclf_user');
    if (!userStr || JSON.parse(userStr).tier !== 'Admin') {
      navigate('/login');
      return;
    }

    // Load initial data
    const savedGallery = localStorage.getItem('uclf_gallery');
    if (savedGallery) {
      setGallery(JSON.parse(savedGallery));
    } else {
      // If nothing in localStorage, show defaults
      setGallery(DEFAULT_GALLERY);
      localStorage.setItem('uclf_gallery', JSON.stringify(DEFAULT_GALLERY));
    }

    const savedPartners = localStorage.getItem('uclf_partners');
    if (savedPartners) setPartners(JSON.parse(savedPartners));

    const savedEvents = localStorage.getItem('uclf_events');
    if (savedEvents) setEvents(JSON.parse(savedEvents));
  }, [navigate]);

  const showNotice = (msg: string, type: 'success' | 'error' = 'success') => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleLogout = () => {
    localStorage.removeItem('uclf_user');
    navigate('/login');
    window.location.reload();
  };

  // Gallery Handlers
  const addImage = () => {
    if (!newImageUrl.trim()) return;
    const updated = [newImageUrl, ...gallery];
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    setNewImageUrl('');
    showNotice('Photo added to scrolling gallery');
  };

  const removeImage = (index: number) => {
    const updated = gallery.filter((_, i) => i !== index);
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    showNotice('Photo removed');
  };

  // Partner Handlers
  const addPartner = () => {
    if (!newPartner.name || !newPartner.type) return;
    const updated = [...partners, newPartner];
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    setNewPartner({ name: '', type: '' });
    showNotice('Strategic partner added');
  };

  const removePartner = (index: number) => {
    const updated = partners.filter((_, i) => i !== index);
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    showNotice('Partner removed');
  };

  // Event Handlers
  const addEvent = () => {
    if (!newEvent.title || !newEvent.date) return;
    const id = 'e' + Date.now();
    const updated = [...events, { ...newEvent, id } as Event];
    setEvents(updated);
    localStorage.setItem('uclf_events', JSON.stringify(updated));
    setNewEvent({
      title: '',
      description: '',
      type: 'Fellowship',
      date: '',
      location: '',
      cleCredits: 0,
      capacity: 50,
      filled: 0,
      imageUrl: ''
    });
    showNotice('Event and calendar program added');
  };

  const removeEvent = (id: string) => {
    const updated = events.filter(e => e.id !== id);
    setEvents(updated);
    localStorage.setItem('uclf_events', JSON.stringify(updated));
    showNotice('Event deleted');
  };

  return (
    <div className="flex h-screen bg-[#f1f5f9] overflow-hidden">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 flex flex-col text-slate-300 shadow-2xl">
        <div className="p-8 border-b border-slate-800">
           <div className="flex items-center space-x-3 text-red-500">
              <div className="bg-red-600/10 p-2 rounded-xl border border-red-500/20">
                <ShieldAlert size={22} />
              </div>
              <span className="font-black text-xl tracking-tight text-white font-serif italic">Admin Console</span>
           </div>
        </div>

        <nav className="p-6 space-y-2 flex-grow">
          {[
            { id: 'gallery', name: 'Gallery Control', icon: <Camera size={18} /> },
            { id: 'partners', name: 'Strategic Partners', icon: <Handshake size={18} /> },
            { id: 'events', name: 'Events & Calendar', icon: <Calendar size={18} /> },
          ].map(item => (
            <button 
              key={item.id} 
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full flex items-center space-x-4 px-5 py-4 rounded-2xl transition-all font-bold text-sm ${activeTab === item.id ? 'bg-red-600 text-white shadow-xl shadow-red-900/40' : 'hover:bg-slate-800 text-slate-400'}`}
            >
              <span>{item.icon}</span>
              <span>{item.name}</span>
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-slate-800">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center space-x-4 px-6 py-4 rounded-xl text-slate-400 hover:text-red-400 hover:bg-red-500/5 transition-all font-black text-xs uppercase tracking-widest"
          >
            <LogOut size={18} />
            <span>Terminate Session</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-grow flex flex-col min-w-0 overflow-y-auto relative">
        {/* Top Header */}
        <header className="bg-white/80 backdrop-blur-md px-10 py-8 border-b border-slate-200 flex items-center justify-between sticky top-0 z-40">
           <div>
              <h1 className="text-3xl font-black text-slate-900 font-serif">
                {activeTab === 'gallery' ? 'Gallery Management' : 
                 activeTab === 'partners' ? 'Strategic Ecosystem' : 'Public Events & Programs'}
              </h1>
              <div className="flex items-center mt-1.5 space-x-2">
                <div className="w-2 h-2 rounded-full bg-red-600 animate-pulse"></div>
                <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Master Authority Access • Real-time Sync Active</p>
              </div>
           </div>

           {notification && (
              <div className={`px-6 py-3 rounded-2xl border flex items-center space-x-3 animate-in fade-in slide-in-from-top-2 duration-300 ${notification.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
                 <CheckCircle size={18} />
                 <span className="text-xs font-black uppercase tracking-widest">{notification.msg}</span>
              </div>
           )}
        </header>

        <div className="p-10 max-w-6xl mx-auto w-full">

          {activeTab === 'gallery' && (
            <div className="space-y-12 animate-in fade-in duration-500">
              <div className="bg-white rounded-[3rem] p-10 shadow-xl border border-slate-100 relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none"><Camera size={180} /></div>
                 <h2 className="text-xl font-black text-slate-900 font-serif mb-8 border-b border-slate-50 pb-4">Add New Activity Photo</h2>
                 <div className="flex flex-col md:flex-row gap-6">
                    <div className="flex-grow">
                       <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Direct Image Link (URL)</label>
                       <input 
                        type="text" 
                        className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                        placeholder="https://images.unsplash.com/..."
                        value={newImageUrl}
                        onChange={e => setNewImageUrl(e.target.value)}
                       />
                       <p className="text-[10px] text-slate-400 mt-3 italic font-medium px-1">Note: Please use high-resolution landscape images for best results in the marquee.</p>
                    </div>
                    <button 
                      onClick={addImage}
                      className="shrink-0 bg-slate-900 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-slate-900/20 active:scale-95 self-end mb-1"
                    >
                      Publish to Gallery
                    </button>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex items-center justify-between px-4">
                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Active Gallery Assets ({gallery.length})</h3>
                    <div className="flex items-center text-[10px] font-bold text-red-500 uppercase tracking-widest"><AlertTriangle size={12} className="mr-1" /> Deletion is permanent</div>
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {gallery.map((img, i) => (
                      <div key={i} className="group relative bg-white p-3 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all">
                        <div className="aspect-[4/3] rounded-2xl overflow-hidden bg-slate-100 border border-slate-100">
                           <img src={img} alt="preview" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                        </div>
                        <button 
                          onClick={() => removeImage(i)}
                          className="absolute -top-3 -right-3 w-10 h-10 bg-white text-red-500 rounded-full shadow-xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity border border-red-50 hover:bg-red-50 hover:scale-110"
                        >
                          <Trash2 size={18} />
                        </button>
                        <div className="mt-3 px-2 flex items-center justify-between">
                           <span className="text-[9px] font-black text-slate-300 uppercase">IMG_ASSET_{i+1}</span>
                           <ExternalLink size={10} className="text-slate-300" />
                        </div>
                      </div>
                    ))}
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'partners' && (
            <div className="space-y-12 animate-in fade-in duration-500">
               <div className="bg-white rounded-[3rem] p-10 shadow-xl border border-slate-100 relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none"><Handshake size={180} /></div>
                 <h2 className="text-xl font-black text-slate-900 font-serif mb-8 border-b border-slate-50 pb-4">Enroll Strategic Partner</h2>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                    <div>
                       <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Entity Name</label>
                       <input 
                        type="text" 
                        className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                        placeholder="e.g. Uganda Law Council"
                        value={newPartner.name}
                        onChange={e => setNewPartner({...newPartner, name: e.target.value})}
                       />
                    </div>
                    <div>
                       <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Partnership Category</label>
                       <input 
                        type="text" 
                        className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                        placeholder="e.g. Regulatory Body"
                        value={newPartner.type}
                        onChange={e => setNewPartner({...newPartner, type: e.target.value})}
                       />
                    </div>
                 </div>
                 <button 
                  onClick={addPartner}
                  className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-slate-900/20 active:scale-[0.99] flex items-center justify-center"
                >
                  <Plus size={18} className="mr-2" /> Authenticate Partner
                </button>
              </div>

              <div className="space-y-6">
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4">Managed Registry ({partners.length})</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {partners.map((p, i) => (
                      <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-xl transition-all">
                        <div className="flex items-center space-x-4">
                           <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center text-slate-900 font-black text-xs shadow-inner">
                              {p.name.charAt(0)}
                           </div>
                           <div>
                              <h4 className="text-sm font-black text-slate-900 leading-none mb-1">{p.name}</h4>
                              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{p.type}</p>
                           </div>
                        </div>
                        <button 
                          onClick={() => removePartner(i)}
                          className="p-3 text-slate-200 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    ))}
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'events' && (
            <div className="space-y-12 animate-in fade-in duration-500">
               <div className="bg-white rounded-[3.5rem] p-12 shadow-xl border border-slate-100">
                  <h2 className="text-2xl font-black text-slate-900 font-serif mb-10 border-b border-slate-50 pb-6 flex items-center">
                    <Calendar className="mr-3 text-red-600" /> Dispatch New Event Listing
                  </h2>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-10">
                     <div className="space-y-6">
                        <div>
                           <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Event Title</label>
                           <input 
                            type="text" 
                            className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                            placeholder="e.g. Constitutional Law Review"
                            value={newEvent.title}
                            onChange={e => setNewEvent({...newEvent, title: e.target.value})}
                           />
                        </div>
                        <div>
                           <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Detailed Description</label>
                           <textarea 
                            rows={4}
                            className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm resize-none"
                            placeholder="Provide deep context for members..."
                            value={newEvent.description}
                            onChange={e => setNewEvent({...newEvent, description: e.target.value})}
                           />
                        </div>
                        <div>
                           <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Event Image URL</label>
                           <input 
                            type="text" 
                            className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                            placeholder="https://images.unsplash.com/..."
                            value={newEvent.imageUrl}
                            onChange={e => setNewEvent({...newEvent, imageUrl: e.target.value})}
                           />
                        </div>
                     </div>
                     <div className="space-y-6">
                        <div className="grid grid-cols-2 gap-6">
                           <div>
                              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Type</label>
                              <select 
                                className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm appearance-none cursor-pointer"
                                value={newEvent.type}
                                onChange={e => setNewEvent({...newEvent, type: e.target.value as any})}
                              >
                                 <option>Fellowship</option>
                                 <option>CLE</option>
                                 <option>Workshop</option>
                                 <option>Conference</option>
                              </select>
                           </div>
                           <div>
                              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">CLE Credits</label>
                              <input 
                                type="number" 
                                className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                                value={newEvent.cleCredits}
                                onChange={e => setNewEvent({...newEvent, cleCredits: parseInt(e.target.value)})}
                              />
                           </div>
                        </div>
                        <div>
                           <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Date & Time String</label>
                           <input 
                            type="text" 
                            className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                            placeholder="April 20, 2024 • 10:00 AM"
                            value={newEvent.date}
                            onChange={e => setNewEvent({...newEvent, date: e.target.value})}
                           />
                        </div>
                        <div>
                           <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Location</label>
                           <input 
                            type="text" 
                            className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
