                      <h3 className="font-black text-gray-900 mb-3 text-base leading-tight hover:text-primary transition-colors cursor-pointer">{article.title}</h3>
                      <p className="text-[10px] font-black text-primary uppercase tracking-widest">{article.date}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

