const AdminDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'gallery' | 'partners' | 'events'>('gallery');

  // Gallery State
  const [gallery, setGallery] = useState<string[]>([]);
  const [newImageUrl, setNewImageUrl] = useState('');

  // Partners State
  const [partners, setPartners] = useState<{name: string, type: string, logoUrl: string}[]>([]);
  const [newPartner, setNewPartner] = useState({ name: '', type: '', logoUrl: '' });

  // Events State
  const [events, setEvents] = useState<Event[]>([]);
  const [newEvent, setNewEvent] = useState<Partial<Event>>({
    title: '',
    description: '',
    type: 'Fellowship',
    date: '',
    location: '',
    cleCredits: 0,
    capacity: 50,
    filled: 0,
    imageUrl: ''
  });

  // Notifications
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => {
    // Check auth
    const userStr = localStorage.getItem('uclf_user');
    if (!userStr || JSON.parse(userStr).tier !== 'Admin') {
      navigate('/login');
      return;
    }

    // Load initial data
    const savedGallery = localStorage.getItem('uclf_gallery');
    if (savedGallery) {
      setGallery(JSON.parse(savedGallery));
    } else {
      // If nothing in localStorage, show defaults
      setGallery(DEFAULT_GALLERY);
      localStorage.setItem('uclf_gallery', JSON.stringify(DEFAULT_GALLERY));
    }

    const savedPartners = localStorage.getItem('uclf_partners');
    if (savedPartners) {
      setPartners(JSON.parse(savedPartners));
    } else {
      setPartners(DEFAULT_PARTNERS);
      localStorage.setItem('uclf_partners', JSON.stringify(DEFAULT_PARTNERS));
    }

    const savedEvents = localStorage.getItem('uclf_events');
    if (savedEvents) setEvents(JSON.parse(savedEvents));
  }, [navigate]);

  const showNotice = (msg: string, type: 'success' | 'error' = 'success') => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleLogout = () => {
    localStorage.removeItem('uclf_user');
    navigate('/login');
    window.location.reload();
  };

  // Gallery Handlers
  const addImage = () => {
    if (!newImageUrl.trim()) return;
    const updated = [newImageUrl, ...gallery];
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    setNewImageUrl('');
    showNotice('Photo added to scrolling gallery');
  };

  const removeImage = (index: number) => {
    const updated = gallery.filter((_, i) => i !== index);
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    showNotice('Photo removed');
  };

  // Partner Handlers
  const addPartner = () => {
    if (!newPartner.name || !newPartner.type || !newPartner.logoUrl) {
      showNotice('Please fill all partner fields including logo URL', 'error');
      return;
    }
    const updated = [newPartner, ...partners];
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    setNewPartner({ name: '', type: '', logoUrl: '' });
    showNotice('Strategic partner authenticated and published');
  };

  const removePartner = (index: number) => {
    const updated = partners.filter((_, i) => i !== index);
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    showNotice('Partner removed from registry');
