                        placeholder="https://images.unsplash.com/..."
                        value={newImageUrl}
                        onChange={e => setNewImageUrl(e.target.value)}
                       />
                       <p className="text-[10px] text-slate-400 mt-3 italic font-medium px-1">Note: Please use high-resolution landscape images for best results in the marquee.</p>
                    </div>
                    <button 
                      onClick={addImage}
                      className="shrink-0 bg-slate-900 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-slate-900/20 active:scale-95 self-end mb-1"
                    >
                      Publish to Gallery
