                                <span className="font-black text-xs text-slate-300">{p.name.charAt(0)}</span>
                              )}
                           </div>
                           <div>
                              <h4 className="text-sm font-black text-slate-900 leading-tight mb-1">{p.name}</h4>
                              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{p.type}</p>
                           </div>
                        </div>
                        <button 
                          onClick={() => removePartner(i)}
                          className="p-3 text-slate-200 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    ))}
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'events' && (
            <div className="space-y-12 animate-in fade-in duration-500">
               <div ref={formRef} className="bg-white rounded-[3.5rem] p-12 shadow-xl border border-slate-100">
                  <div className="flex items-center justify-between mb-10 border-b border-slate-50 pb-6">
                    <h2 className="text-2xl font-black text-slate-900 font-serif flex items-center">
                      <Calendar className="mr-3 text-red-600" /> 
                      {editingEventId ? 'Modify Scheduled Event' : 'Dispatch New Event Listing'}
                    </h2>
                    {editingEventId && (
                      <button onClick={cancelEdit} className="text-xs font-black text-slate-400 hover:text-red-600 uppercase flex items-center transition-colors">
                        <X size={14} className="mr-1" /> Discard Changes
                      </button>
