                                 <option>CLE</option>
                                 <option>Workshop</option>
                                 <option>Conference</option>
                              </select>
                           </div>
                           <div>
                              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">CLE Credits</label>
