                            value={newEvent.date}
                            onChange={e => setNewEvent({...newEvent, date: e.target.value})}
                           />
                           <p className="text-[9px] text-slate-400 mt-2 italic px-1">Recommended Format: "Month Day, Year • Time"</p>
                        </div>
                        <div>
