                                 <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">{e.date} • {e.filled}/{e.capacity} Registered</p>
                              </div>
                           </div>
                           <div className="flex items-center space-x-3">
                              <button 
                                 onClick={() => startEditEvent(e)}
                                 className={`p-4 rounded-2xl transition-all shadow-sm ${editingEventId === e.id ? 'bg-red-600 text-white' : 'bg-slate-50 text-slate-600 hover:bg-slate-900 hover:text-white opacity-0 group-hover:opacity-100'}`}
                                 title="Edit Event"
                              >
                                 <Edit3 size={20} />
                              </button>
                              <button 
                               onClick={() => removeEvent(e.id)}
                               className="bg-red-50 text-red-600 p-4 rounded-2xl hover:bg-red-600 hover:text-white transition-all opacity-0 group-hover:opacity-100 shadow-sm"
                               title="Delete Event"
                              >
                                 <Trash2 size={20} />
                              </button>
                           </div>
                        </div>
                     ))}

                     {events.length === 0 && (
                        <div className="py-20 text-center bg-white rounded-[3rem] border border-slate-100 shadow-inner">
                           <Calendar size={48} className="mx-auto text-slate-200 mb-4" />
                           <h4 className="text-lg font-black text-slate-400 font-serif">No Events on Registry</h4>
                           <p className="text-sm text-slate-400">Use the form above to populate the public calendar.</p>
                        </div>
                     )}
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

