                          <input type="number" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="CLE Credits" value={newEvent.cleCredits} onChange={e => setNewEvent({...newEvent, cleCredits: parseInt(e.target.value)})} />
