                          placeholder="e.g. Regulatory Body"
                          value={newPartner.type}
                          onChange={e => setNewPartner({...newPartner, type: e.target.value})}
                        />
                      </div>
                    </div>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Partner Logo URL</label>
                        <input 
                          type="text" 
                          className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                          placeholder="https://..."
                          value={newPartner.logoUrl}
                          onChange={e => setNewPartner({...newPartner, logoUrl: e.target.value})}
                        />
                      </div>
                      <div className="bg-slate-50 rounded-2xl p-4 border border-dashed border-slate-200 h-[100px] flex items-center justify-center overflow-hidden">
                        {newPartner.logoUrl ? (
                          <img src={newPartner.logoUrl} alt="Logo Preview" className="max-h-full max-w-full object-contain" />
                        ) : (
                          <div className="text-[10px] font-black text-slate-300 uppercase">Logo Preview Area</div>
                        )}
                      </div>
                    </div>
                 </div>
                 <button 
                  onClick={addPartner}
                  className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-slate-900/20 active:scale-[0.99] flex items-center justify-center"
                >
                  <Plus size={18} className="mr-2" /> Authenticate Partner
                </button>
              </div>

              <div className="space-y-6">
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4">Managed Registry ({partners.length})</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {partners.map((p, i) => (
                      <div key={i} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-xl transition-all">
                        <div className="flex items-center space-x-5">
                           <div className="w-20 h-12 bg-slate-50 rounded-xl flex items-center justify-center overflow-hidden shadow-inner p-2 border border-slate-100">
                              {p.logoUrl ? (
                                <img src={p.logoUrl} alt={p.name} className="max-h-full max-w-full object-contain" />
                              ) : (
                                <span className="font-black text-xs text-slate-300">{p.name.charAt(0)}</span>
                              )}
                           </div>
                           <div>
                              <h4 className="text-sm font-black text-slate-900 leading-tight mb-1">{p.name}</h4>
                              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{p.type}</p>
                           </div>
                        </div>
                        <button 
                          onClick={() => removePartner(i)}
                          className="p-3 text-slate-200 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    ))}
                 </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

