const AdminDashboard: React.FC = () => {
  const navigate = useNavigate();
  const formRef = useRef<HTMLDivElement>(null);
  const resourceFormRef = useRef<HTMLDivElement>(null);

  const [activeTab, setActiveTab] = useState<'gallery' | 'partners' | 'events' | 'news' | 'resources'>('gallery');

  // States
  const [gallery, setGallery] = useState<string[]>([]);
  const [partners, setPartners] = useState<{name: string, type: string, logoUrl: string}[]>([]);
  const [events, setEvents] = useState<Event[]>([]);
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [resources, setResources] = useState<Resource[]>([]);

  // Filtering Resource States
  const [resSearch, setResSearch] = useState('');
  const [resTypeFilter, setResTypeFilter] = useState<'All' | Resource['type']>('All');

  // Individual Form States
  const [newImageUrl, setNewImageUrl] = useState('');
  const [newPartner, setNewPartner] = useState({ name: '', type: '', logoUrl: '' });

  const [editingEventId, setEditingEventId] = useState<string | null>(null);
  const [newEvent, setNewEvent] = useState<Partial<Event>>({
    title: '', description: '', type: 'Fellowship', date: '', location: '', cleCredits: 0, capacity: 50, filled: 0, imageUrl: ''
  });

  const [editingNewsId, setEditingNewsId] = useState<string | null>(null);
  const [newArticle, setNewArticle] = useState<Partial<NewsArticle>>({
    title: '', excerpt: '', content: '', date: '', imageUrl: '', category: 'General'
  });

  const [editingResourceId, setEditingResourceId] = useState<string | null>(null);
  const [newResource, setNewResource] = useState<Partial<Resource>>({
    title: '', category: 'Legal Templates', date: '', type: 'PDF', downloadUrl: '', description: ''
  });

  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => {
    const userStr = localStorage.getItem('uclf_user');
    if (!userStr || JSON.parse(userStr).tier !== 'Admin') {
      navigate('/login');
      return;
    }

    const loadData = (key: string, initial: any, setter: Function) => {
      const saved = localStorage.getItem(key);
      if (saved) setter(JSON.parse(saved));
      else {
        setter(initial);
        localStorage.setItem(key, JSON.stringify(initial));
      }
    };

    loadData('uclf_gallery', DEFAULT_GALLERY, setGallery);
    loadData('uclf_partners', DEFAULT_PARTNERS, setPartners);
    loadData('uclf_events', INITIAL_EVENTS, setEvents);
    loadData('uclf_news', INITIAL_NEWS, setNews);
    loadData('uclf_resources', INITIAL_RESOURCES, setResources);
  }, [navigate]);

  const showNotice = (msg: string, type: 'success' | 'error' = 'success') => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleLogout = () => {
    localStorage.removeItem('uclf_user');
    navigate('/login');
    window.location.reload();
  };

  // HANDLERS
  const addImage = () => {
    if (!newImageUrl.trim()) return;
    const updated = [newImageUrl, ...gallery];
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    setNewImageUrl('');
    showNotice('Photo added');
  };

  const removeImage = (index: number) => {
    const updated = gallery.filter((_, i) => i !== index);
    setGallery(updated);
    localStorage.setItem('uclf_gallery', JSON.stringify(updated));
    showNotice('Photo removed');
  };

  const addPartner = () => {
    if (!newPartner.name || !newPartner.logoUrl) return;
    const updated = [newPartner, ...partners];
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    setNewPartner({ name: '', type: '', logoUrl: '' });
    showNotice('Partner added');
  };

  const removePartner = (index: number) => {
    const updated = partners.filter((_, i) => i !== index);
    setPartners(updated);
    localStorage.setItem('uclf_partners', JSON.stringify(updated));
    showNotice('Partner removed');
  };

  const addEvent = () => {
    if (!newEvent.title || !newEvent.date) return;
    let updated: Event[];
    if (editingEventId) {
      updated = events.map(e => e.id === editingEventId ? { ...newEvent, id: editingEventId } as Event : e);
    } else {
      updated = [{ ...newEvent, id: 'e' + Date.now() } as Event, ...events];
    }
    setEvents(updated);
    localStorage.setItem('uclf_events', JSON.stringify(updated));
    setEditingEventId(null);
    setNewEvent({ title: '', description: '', type: 'Fellowship', date: '', location: '', cleCredits: 0, capacity: 50, filled: 0, imageUrl: '' });
    showNotice(editingEventId ? 'Event updated' : 'Event published');
  };

  const addNews = () => {
    if (!newArticle.title || !newArticle.date) return;
    let updated: NewsArticle[];
    if (editingNewsId) {
      updated = news.map(a => a.id === editingNewsId ? { ...newArticle, id: editingNewsId } as NewsArticle : a);
    } else {
      updated = [{ ...newArticle, id: 'n' + Date.now() } as NewsArticle, ...news];
    }
    setNews(updated);
    localStorage.setItem('uclf_news', JSON.stringify(updated));
    setEditingNewsId(null);
    setNewArticle({ title: '', excerpt: '', content: '', date: '', imageUrl: '', category: 'General' });
    showNotice(editingNewsId ? 'News updated' : 'News published');
  };

  const addResource = () => {
    if (!newResource.title || !newResource.downloadUrl) {
      showNotice('Please provide title and download URL', 'error');
      return;
    }
    let updated: Resource[];
    if (editingResourceId) {
      updated = resources.map(r => r.id === editingResourceId ? { ...newResource, id: editingResourceId } as Resource : r);
      showNotice('Resource updated successfully');
    } else {
      updated = [{ ...newResource, id: 'r' + Date.now() } as Resource, ...resources];
      showNotice('New resource published to library');
    }
    setResources(updated);
    localStorage.setItem('uclf_resources', JSON.stringify(updated));
    resetResourceForm();
  };

  const resetResourceForm = () => {
    setEditingResourceId(null);
    setNewResource({ title: '', category: 'Legal Templates', date: '', type: 'PDF', downloadUrl: '', description: '' });
  };

  const startEditingResource = (r: Resource) => {
    setEditingResourceId(r.id);
    setNewResource(r);
    resourceFormRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const deleteResource = (id: string) => {
    if (window.confirm('Are you sure you want to permanently delete this asset from the fraternity library?')) {
      const updated = resources.filter(r => r.id !== id);
      setResources(updated);
      localStorage.setItem('uclf_resources', JSON.stringify(updated));
      showNotice('Resource deleted');
      if (editingResourceId === id) resetResourceForm();
    }
  };

  const getResourceIcon = (type: Resource['type']) => {
    switch (type) {
      case 'Audio': return <Music size={24} />;
      case 'Video': return <Video size={24} />;
      case 'Case': return <Scale size={24} />;
      default: return <FileText size={24} />;
    }
  };

  const filteredResources = resources.filter(r => {
    const matchesSearch = r.title.toLowerCase().includes(resSearch.toLowerCase());
    const matchesType = resTypeFilter === 'All' || r.type === resTypeFilter;
    return matchesSearch && matchesType;
  });

  return (
    <div className="flex h-screen bg-[#f1f5f9] overflow-hidden">
      {/* Sidebar */}
      <aside className="w-72 bg-slate-900 flex flex-col text-slate-300 shadow-2xl shrink-0">
        <div className="p-8 border-b border-slate-800">
           <div className="flex items-center space-x-3 text-red-500">
              <div className="bg-red-600/10 p-2 rounded-xl border border-red-500/20">
                <ShieldAlert size={22} />
              </div>
              <span className="font-black text-xl tracking-tight text-white font-serif italic">Admin Console</span>
           </div>
        </div>

        <nav className="p-6 space-y-2 flex-grow overflow-y-auto">
          {[
            { id: 'gallery', name: 'Gallery Control', icon: <Camera size={18} /> },
            { id: 'partners', name: 'Strategic Partners', icon: <Handshake size={18} /> },
            { id: 'events', name: 'Events & Calendar', icon: <Calendar size={18} /> },
            { id: 'news', name: 'News & Bulletins', icon: <Newspaper size={18} /> },
            { id: 'resources', name: 'Library & Assets', icon: <BookOpen size={18} /> },
          ].map(item => (
            <button 
              key={item.id} 
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full flex items-center space-x-4 px-5 py-4 rounded-2xl transition-all font-bold text-sm ${activeTab === item.id ? 'bg-red-600 text-white shadow-xl shadow-red-900/40' : 'hover:bg-slate-800 text-slate-400'}`}
            >
              <span>{item.icon}</span>
              <span>{item.name}</span>
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-slate-800">
          <button onClick={handleLogout} className="w-full flex items-center space-x-4 px-6 py-4 rounded-xl text-slate-400 hover:text-red-400 hover:bg-red-500/5 transition-all font-black text-xs uppercase tracking-widest">
            <LogOut size={18} />
            <span>Terminate Session</span>
          </button>
        </div>
      </aside>

      <main className="flex-grow flex flex-col min-w-0 overflow-y-auto relative">
        <header className="bg-white/80 backdrop-blur-md px-10 py-8 border-b border-slate-200 flex items-center justify-between sticky top-0 z-40">
           <div>
              <h1 className="text-3xl font-black text-slate-900 font-serif lowercase capitalize">{activeTab.replace('-', ' ')} management</h1>
              <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Master Authority Access • Real-time Sync Active</p>
           </div>
           {notification && (
              <div className={`px-6 py-3 rounded-2xl border flex items-center space-x-3 animate-in fade-in slide-in-from-top-2 duration-300 ${notification.type === 'success' ? 'bg-emerald-50 border-emerald-100 text-emerald-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
                 <CheckCircle size={18} />
                 <span className="text-xs font-black uppercase tracking-widest">{notification.msg}</span>
              </div>
           )}
        </header>

        <div className="p-10 max-w-6xl mx-auto w-full">
          {activeTab === 'gallery' && (
            <div className="space-y-12 animate-in fade-in duration-500">
              <div className="bg-white rounded-[3rem] p-10 shadow-xl border border-slate-100">
                 <h2 className="text-xl font-black text-slate-900 font-serif mb-8 border-b border-slate-50 pb-4">Add Photo</h2>
                 <div className="flex flex-col md:flex-row gap-6">
                    <input type="text" className="flex-grow px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Image URL..." value={newImageUrl} onChange={e => setNewImageUrl(e.target.value)} />
                    <button onClick={addImage} className="bg-slate-900 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all">Publish</button>
                 </div>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                {gallery.map((img, i) => (
                  <div key={i} className="group relative bg-white p-3 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all">
                    <img src={img} alt="p" className="w-full aspect-square object-cover rounded-2xl" />
                    <button onClick={() => removeImage(i)} className="absolute -top-2 -right-2 bg-white text-red-500 p-2 rounded-full shadow-lg opacity-0 group-hover:opacity-100"><Trash2 size={16} /></button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'resources' && (
            <div className="space-y-12 animate-in fade-in duration-500">
               <div ref={resourceFormRef} className={`bg-white rounded-[3.5rem] p-12 shadow-xl border transition-all duration-300 ${editingResourceId ? 'border-red-200 ring-4 ring-red-50' : 'border-slate-100'}`}>
                  <div className="flex items-center justify-between mb-10 border-b border-slate-50 pb-6">
                    <h2 className="text-2xl font-black text-slate-900 font-serif flex items-center">
                      <BookOpen className={`mr-3 ${editingResourceId ? 'text-red-600' : 'text-primary'}`} /> 
                      {editingResourceId ? 'Modify Existing Asset' : 'Upload New Resource'}
                    </h2>
                    {editingResourceId && (
                      <button onClick={resetResourceForm} className="text-xs font-black text-slate-400 hover:text-red-600 uppercase flex items-center transition-colors">
                        <X size={14} className="mr-1" /> Cancel Edit
                      </button>
                    )}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-10">
                     <div className="space-y-6">
                        <div>
                           <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Resource Title</label>
                           <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="e.g. Tenancy Agreement Template" value={newResource.title} onChange={e => setNewResource({...newResource, title: e.target.value})} />
                        </div>
                        <div>
                           <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Category</label>
                           <select className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm appearance-none cursor-pointer" value={newResource.category} onChange={e => setNewResource({...newResource, category: e.target.value as any})}>
                              <option value="Legal Templates">Legal Templates</option>
                              <option value="Case Law">Case Law</option>
                              <option value="Christian Ethics">Christian Ethics</option>
                              <option value="Audios">Audios</option>
                              <option value="Videos">Videos</option>
                              <option value="Reports">Reports</option>
                           </select>
                        </div>
                        <div>
                           <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Download/Asset Link (URL)</label>
                           <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="https://..." value={newResource.downloadUrl} onChange={e => setNewResource({...newResource, downloadUrl: e.target.value})} />
                        </div>
                     </div>
                     <div className="space-y-6">
                        <div className="grid grid-cols-2 gap-6">
                           <div>
                              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Display Date</label>
                              <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="e.g. Mar 2024" value={newResource.date} onChange={e => setNewResource({...newResource, date: e.target.value})} />
                           </div>
                           <div>
                              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Asset Format</label>
                              <select className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" value={newResource.type} onChange={e => setNewResource({...newResource, type: e.target.value as any})}>
                                 <option value="PDF">PDF Document</option>
                                 <option value="DOC">Word Document</option>
                                 <option value="Case">Case Brief</option>
                                 <option value="Audio">Audio Clip</option>
                                 <option value="Video">Video/Webinar</option>
                              </select>
                           </div>
                        </div>
                        <div>
                           <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Description (Optional)</label>
                           <textarea rows={3} className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm resize-none" placeholder="Brief context for members..." value={newResource.description} onChange={e => setNewResource({...newResource, description: e.target.value})} />
                        </div>
                     </div>
                  </div>
                  <button onClick={addResource} className={`w-full py-6 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl active:scale-95 transition-all text-white ${editingResourceId ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-red-600 hover:bg-red-700'}`}>
                    {editingResourceId ? 'Authorize & Apply Updates' : 'Commit Resource to Library'}
                  </button>
               </div>

               <div className="space-y-6">
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-4">
                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Managed Digital Assets ({filteredResources.length})</h3>

                    {/* Search and Filter UI */}
                    <div className="flex flex-col sm:flex-row items-center gap-4 flex-grow max-w-2xl">
                      <div className="relative flex-grow w-full">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input 
                          type="text"
                          placeholder="Search assets by name..."
                          className="w-full pl-11 pr-4 py-3 rounded-xl bg-white border border-slate-200 outline-none focus:ring-4 focus:ring-red-500/5 text-sm font-medium transition-all"
                          value={resSearch}
                          onChange={e => setResSearch(e.target.value)}
                        />
                      </div>
                      <div className="flex items-center space-x-2 bg-white px-4 py-3 rounded-xl border border-slate-200 shrink-0">
                        <Filter size={16} className="text-slate-400" />
                        <select 
                          className="bg-transparent text-xs font-bold uppercase tracking-widest outline-none cursor-pointer"
                          value={resTypeFilter}
                          onChange={e => setResTypeFilter(e.target.value as any)}
                        >
                          <option value="All">All Formats</option>
                          <option value="PDF">PDF Only</option>
                          <option value="DOC">DOC Only</option>
                          <option value="Audio">Audio Only</option>
                          <option value="Video">Video Only</option>
                          <option value="Case">Case Only</option>
                        </select>
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 gap-4">
                    {filteredResources.map(r => (
                      <div key={r.id} className={`bg-white p-6 rounded-[2.5rem] border transition-all flex items-center justify-between group hover:shadow-xl ${editingResourceId === r.id ? 'border-red-500 ring-2 ring-red-500/10' : 'border-slate-100 hover:border-red-100'}`}>
                         <div className="flex items-center space-x-8">
                            <div className={`w-16 h-16 rounded-2xl flex items-center justify-center shadow-inner relative transition-transform duration-500 group-hover:scale-110 ${
                              r.type === 'Audio' ? 'bg-orange-50 text-orange-600' : 
                              r.type === 'Video' ? 'bg-purple-50 text-purple-600' : 
                              r.type === 'Case' ? 'bg-blue-50 text-blue-600' :
                              'bg-red-50 text-red-600'
                            }`}>
                               {getResourceIcon(r.type)}
                               {editingResourceId === r.id && (
                                 <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-600 rounded-full border-2 border-white animate-pulse"></div>
                               )}
                            </div>
                            <div>
                               <h4 className="font-black text-slate-900 text-lg group-hover:text-primary transition-colors">{r.title}</h4>
                               <div className="flex items-center space-x-4 mt-1">
                                  <span className="px-3 py-0.5 rounded-lg bg-slate-50 text-[9px] font-black text-slate-500 uppercase tracking-widest border border-slate-100">{r.category}</span>
                                  <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest flex items-center"><Calendar size={10} className="mr-1.5" /> {r.date}</span>
                                  <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest flex items-center"><Download size={10} className="mr-1.5" /> {r.type}</span>
                               </div>
                            </div>
                         </div>
                         <div className="flex items-center space-x-3">
                            <button 
                              onClick={() => startEditingResource(r)} 
                              className={`p-4 rounded-2xl transition-all shadow-sm ${editingResourceId === r.id ? 'bg-red-600 text-white' : 'bg-slate-50 text-slate-600 hover:bg-slate-900 hover:text-white opacity-0 group-hover:opacity-100'}`}
                              title="Edit Asset"
                            >
                               <Edit3 size={18} />
                            </button>
                            <button 
                              onClick={() => deleteResource(r.id)} 
                              className="p-4 bg-red-50 text-red-600 rounded-2xl hover:bg-red-600 hover:text-white transition-all opacity-0 group-hover:opacity-100 shadow-sm"
                              title="Delete Asset"
                            >
                               <Trash2 size={18} />
                            </button>
                         </div>
                      </div>
                    ))}

                    {filteredResources.length === 0 && (
                      <div className="py-24 text-center bg-white rounded-[3rem] border-2 border-dashed border-slate-200">
                         {resources.length === 0 ? (
                           <>
                            <BookOpen size={48} className="mx-auto text-slate-200 mb-4" />
                            <h4 className="text-xl font-black text-slate-400 font-serif">Resource Library is Empty</h4>
                            <p className="text-sm text-slate-400">Use the form above to enroll new legal assets and professional guides.</p>
                           </>
                         ) : (
                           <>
                            <Search size={48} className="mx-auto text-slate-200 mb-4" />
                            <h4 className="text-xl font-black text-slate-400 font-serif">No assets match your filters</h4>
                            <p className="text-sm text-slate-400">Try adjusting your search query or format filter.</p>
                            <button onClick={() => { setResSearch(''); setResTypeFilter('All'); }} className="mt-4 text-xs font-black text-primary uppercase tracking-widest hover:underline">Clear all filters</button>
                           </>
                         )}
                      </div>
                    )}
                  </div>
               </div>
            </div>
          )}

