      const newFiles = Array.from(e.target.files).map((f: File) => ({
        id: Math.random().toString(36).substring(7),
        file: f,
        progress: 100,
        error: f.size > 5 * 1024 * 1024 ? "File too large (>5MB)" : undefined
      }));
      setFiles(prev => [...prev, ...newFiles]);
