                  <button className="bg-red-600 text-white px-10 py-5 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-red-700 hover:scale-105 active:scale-95 transition-all shadow-xl shadow-red-200">Initiate Request</button>
               </div>
            </div>
          )}
        </div>
      </main>

      {/* Case Intake Modal */}
      {isIntakeModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-primary/20 backdrop-blur-md" onClick={() => setIsIntakeModalOpen(false)}></div>
          <div className="bg-white rounded-[3rem] w-full max-w-3xl relative z-10 shadow-2xl overflow-hidden animate-in zoom-in duration-300">
             <header className="bg-primary p-10 text-white flex items-center justify-between">
                <div>
                   <h2 className="text-3xl font-black font-serif">New Case Intake</h2>
                   <p className="text-xs text-blue-200 uppercase font-black tracking-widest mt-1">UCLF Legal Aid Repository</p>
                </div>
                <button onClick={() => setIsIntakeModalOpen(false)} className="p-3 hover:bg-white/10 rounded-full transition-colors"><X size={28} /></button>
             </header>
             <form onSubmit={handleCreateCase} className="p-12 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-3">
                      <label className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Applicant Full Name</label>
                      <input 
                        required 
                        type="text" 
                        className="w-full px-6 py-5 rounded-2xl bg-gray-50 border-none outline-none font-medium text-sm focus:ring-4 focus:ring-primary/5 transition-all"
                        placeholder="e.g. Namyalo Beatrice"
                        value={newCase.requesterName}
                        onChange={e => setNewCase({...newCase, requesterName: e.target.value})}
                      />
                   </div>
                   <div className="space-y-3">
                      <label className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Legal Aid Program</label>
                      <select 
                        className="w-full px-6 py-5 rounded-2xl bg-gray-50 border-none outline-none font-medium text-sm focus:ring-4 focus:ring-primary/5 transition-all appearance-none cursor-pointer"
                        value={newCase.program}
                        onChange={e => setNewCase({...newCase, program: e.target.value as LegalProgram})}
                      >
                        {Object.values(LegalProgram).map(p => <option key={p} value={p}>{p}</option>)}
                      </select>
                   </div>
                </div>
                <div className="space-y-3">
                   <label className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Priority / Urgency Level</label>
                   <div className="grid grid-cols-3 gap-4">
                      {Object.values(UrgencyLevel).map(u => (
                        <button 
                          key={u} 
                          type="button" 
                          onClick={() => setNewCase({...newCase, urgency: u})}
                          className={`py-4 rounded-2xl font-black text-xs uppercase tracking-widest border-2 transition-all ${newCase.urgency === u ? 'border-primary bg-primary text-white shadow-lg' : 'border-gray-100 text-gray-400 hover:border-gray-200'}`}
                        >
                          {u}
                        </button>
                      ))}
                   </div>
                </div>
                <div className="space-y-3">
                   <label className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Initial Case Summary</label>
                   <textarea 
                    required 
                    rows={4} 
                    className="w-full px-6 py-5 rounded-2xl bg-gray-50 border-none outline-none font-medium text-sm focus:ring-4 focus:ring-primary/5 transition-all resize-none"
                    placeholder="Provide a brief summary of the legal issue and indigent status..."
                    value={newCase.description}
                    onChange={e => setNewCase({...newCase, description: e.target.value})}
                   />
                </div>
                <div className="pt-6">
                   <button type="submit" className="w-full py-5 bg-primary text-white rounded-[1.5rem] font-black uppercase tracking-widest text-sm shadow-xl hover:bg-blue-800 transition-all flex items-center justify-center">
                     <Save size={20} className="mr-3" /> Save and Sync Case
                   </button>
                </div>
             </form>
          </div>
        </div>
      )}

      {/* Case Detail Modal */}
      {isDetailModalOpen && selectedCase && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsDetailModalOpen(false)}></div>
          <div className="bg-white rounded-[3rem] w-full max-w-4xl relative z-10 shadow-2xl overflow-hidden animate-in slide-in-from-bottom-8 duration-400">
             <div className="flex h-full flex-col md:flex-row">
                {/* Left: Detail Info */}
                <div className="flex-grow p-12 overflow-y-auto max-h-[80vh]">
                   <div className="flex items-center justify-between mb-10">
                      <span className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 ${getUrgencyColor(selectedCase.urgency)}`}>
                        {selectedCase.urgency} Urgency
                      </span>
                      <button onClick={() => setIsDetailModalOpen(false)} className="p-2 text-gray-400 hover:bg-gray-100 rounded-full"><X size={24} /></button>
                   </div>

                   <h2 className="text-4xl font-black text-gray-900 font-serif mb-2">{selectedCase.caseRef}</h2>
                   <p className="text-lg text-primary font-bold mb-10">Applicant: {selectedCase.requesterName}</p>

                   <div className="grid grid-cols-2 gap-8 mb-12">
                      <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Legal Program</p>
                         <p className="font-bold text-gray-900">{selectedCase.program}</p>
                      </div>
                      <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Current Venue</p>
                         <p className="font-bold text-gray-900">{selectedCase.courtLevel}</p>
                      </div>
                   </div>

                   <div className="space-y-6">
                      <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest border-b border-gray-100 pb-2">Case Narrative</h3>
                      <p className="text-gray-600 leading-relaxed italic">"{selectedCase.description}"</p>

                      <div className="bg-blue-50/50 p-8 rounded-[2rem] border border-blue-100 flex items-start space-x-4">
                         <div className="bg-primary p-3 rounded-2xl text-secondary shadow-lg shrink-0"><MessageSquare size={20} /></div>
                         <div>
                            <p className="text-[10px] font-black text-primary uppercase tracking-widest mb-1">Secretariat Note</p>
                            <p className="text-sm font-medium text-blue-900">Verification complete. Indigent status confirmed via Regional Hub. Pro-bono assignment pending final counsel signature.</p>
                         </div>
                      </div>
                   </div>
                </div>

                {/* Right: Actions */}
                <div className="w-full md:w-80 bg-gray-50 p-12 border-l border-gray-100 flex flex-col">
                   <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest mb-10">Update Workflow</h3>
                   <div className="space-y-4 flex-grow">
                      {[
                        { status: CaseStatus.ASSIGNED, color: 'bg-blue-600 text-white' },
                        { status: CaseStatus.IN_PROGRESS, color: 'bg-yellow-500 text-white' },
                        { status: CaseStatus.RESOLVED, color: 'bg-green-600 text-white' },
                        { status: CaseStatus.CLOSED, color: 'bg-gray-800 text-white' }
                      ].map(s => (
                        <button 
                          key={s.status}
                          onClick={() => updateCaseStatus(selectedCase.id, s.status)}
                          className={`w-full py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-md hover:scale-[1.03] active:scale-[0.98] ${s.color}`}
                        >
                          Mark as {s.status}
                        </button>
                      ))}
                   </div>

                   <div className="mt-12 pt-10 border-t border-gray-200">
                      <button className="w-full py-4 bg-white border border-gray-200 text-gray-500 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center hover:bg-gray-100 transition-colors">
                        <Download size={16} className="mr-2" /> Download Dossier
                      </button>
                      <button className="w-full mt-4 py-4 bg-white border border-gray-200 text-red-500 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center hover:bg-red-50 transition-colors">
                        <Trash2 size={16} className="mr-2" /> Delete Record
                      </button>
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CaseManagement;

