                   {editingNewsId ? 'Update Bulletin' : 'Draft New Bulletin'}
                 </h2>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-10">
                    <div className="space-y-6">
                      <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Headline" value={newArticle.title} onChange={e => setNewArticle({...newArticle, title: e.target.value})} />
                      <textarea rows={3} className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Excerpt (Short summary)" value={newArticle.excerpt} onChange={e => setNewArticle({...newArticle, excerpt: e.target.value})} />
                      <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Image URL" value={newArticle.imageUrl} onChange={e => setNewArticle({...newArticle, imageUrl: e.target.value})} />
                    </div>
                    <div className="space-y-6">
                      <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Date (e.g. March 30, 2024)" value={newArticle.date} onChange={e => setNewArticle({...newArticle, date: e.target.value})} />
                      <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Category" value={newArticle.category} onChange={e => setNewArticle({...newArticle, category: e.target.value})} />
                      <textarea rows={4} className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Full Article Content..." value={newArticle.content} onChange={e => setNewArticle({...newArticle, content: e.target.value})} />
                    </div>
                 </div>
                 <button onClick={addNews} className="w-full py-6 bg-red-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl">{editingNewsId ? 'Apply Update' : 'Publish Bulletin'}</button>
              </div>
