                             <h4 className="font-black text-slate-900">{a.title}</h4>
                             <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{a.date} • {a.category}</p>
                          </div>
                       </div>
                       <div className="flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setEditingNewsId(a.id); setNewArticle(a); }} className="p-3 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-900 hover:text-white"><Edit3 size={18} /></button>
