                  <h2 className="text-2xl font-black text-slate-900 font-serif mb-10 border-b border-slate-50 pb-6 flex items-center">
                    <Calendar className="mr-3 text-red-600" /> {editingEventId ? 'Update Event' : 'Dispatch Event Listing'}
