                     </div>
                     <div className="space-y-6">
                        <div className="grid grid-cols-2 gap-6">
                          <select className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" value={newEvent.type} onChange={e => setNewEvent({...newEvent, type: e.target.value as any})}><option>Fellowship</option><option>CLE</option><option>Workshop</option><option>Conference</option></select>
