                        <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Date (April 20, 2024)" value={newEvent.date} onChange={e => setNewEvent({...newEvent, date: e.target.value})} />
                        <input type="text" className="w-full px-6 py-4 rounded-2xl bg-slate-50 border-none outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm" placeholder="Location" value={newEvent.location} onChange={e => setNewEvent({...newEvent, location: e.target.value})} />
                     </div>
                  </div>
                  <button onClick={addEvent} className="w-full py-6 bg-red-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl">{editingEventId ? 'Update' : 'Publish'}</button>
               </div>
               <div className="space-y-4">
                  {events.map(e => (
                     <div key={e.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 flex items-center justify-between group">
                        <div className="flex items-center space-x-8">
                           <div className="w-16 h-16 bg-slate-900 rounded-2xl flex flex-col items-center justify-center text-white">
                              <span className="text-[10px] font-black">{e.date.split(' ')[0]}</span>
                              <span className="text-xl font-black">{e.date.split(' ')[1]?.replace(',', '')}</span>
                           </div>
                           <div>
                              <h4 className="font-black text-slate-900">{e.title}</h4>
                              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{e.location}</p>
                           </div>
                        </div>
                        <div className="flex space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                           <button onClick={() => { setEditingEventId(e.id); setNewEvent(e); }} className="p-3 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-900 hover:text-white"><Edit3 size={18} /></button>
                           <button onClick={() => { const u = events.filter(x => x.id !== e.id); setEvents(u); localStorage.setItem('uclf_events', JSON.stringify(u)); }} className="p-3 bg-red-50 text-red-600 rounded-xl hover:bg-red-600 hover:text-white"><Trash2 size={18} /></button>
                        </div>
                     </div>
                  ))}
               </div>
            </div>
          )}

          {activeTab === 'partners' && (
            <div className="space-y-12 animate-in fade-in duration-500">
               <div className="bg-white rounded-[3rem] p-10 shadow-xl border border-slate-100 relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none"><Handshake size={180} /></div>
                 <h2 className="text-xl font-black text-slate-900 font-serif mb-8 border-b border-slate-50 pb-4">Enroll Strategic Partner</h2>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
                    <div className="space-y-6">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Entity Name</label>
                        <input 
                          type="text" 
                          className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                          placeholder="e.g. Uganda Law Council"
                          value={newPartner.name}
                          onChange={e => setNewPartner({...newPartner, name: e.target.value})}
                        />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Partnership Category</label>
                        <input 
                          type="text" 
                          className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                          placeholder="e.g. Regulatory Body"
                          value={newPartner.type}
                          onChange={e => setNewPartner({...newPartner, type: e.target.value})}
                        />
                      </div>
                    </div>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Partner Logo URL</label>
                        <input 
                          type="text" 
                          className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-100 outline-none focus:ring-4 focus:ring-red-500/5 focus:bg-white transition-all font-bold text-sm"
                          placeholder="https://..."
                          value={newPartner.logoUrl}
                          onChange={e => setNewPartner({...newPartner, logoUrl: e.target.value})}
                        />
                      </div>
                      <div className="bg-slate-50 rounded-2xl p-4 border border-dashed border-slate-200 h-[100px] flex items-center justify-center overflow-hidden">
                        {newPartner.logoUrl ? (
                          <img src={newPartner.logoUrl} alt="Logo Preview" className="max-h-full max-w-full object-contain" />
                        ) : (
                          <div className="text-[10px] font-black text-slate-300 uppercase">Logo Preview Area</div>
                        )}
                      </div>
                    </div>
                 </div>
                 <button 
                  onClick={addPartner}
                  className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-slate-900/20 active:scale-[0.99] flex items-center justify-center"
                >
                  <Plus size={18} className="mr-2" /> Authenticate Partner
                </button>
              </div>

              <div className="space-y-6">
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4">Managed Registry ({partners.length})</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {partners.map((p, i) => (
                      <div key={i} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-xl transition-all">
                        <div className="flex items-center space-x-5">
                           <div className="w-20 h-12 bg-slate-50 rounded-xl flex items-center justify-center overflow-hidden shadow-inner p-2 border border-slate-100">
                              {p.logoUrl ? (
                                <img src={p.logoUrl} alt={p.name} className="max-h-full max-w-full object-contain" />
                              ) : (
                                <span className="font-black text-xs text-slate-300">{p.name.charAt(0)}</span>
                              )}
                           </div>
                           <div>
                              <h4 className="text-sm font-black text-slate-900 leading-tight mb-1">{p.name}</h4>
                              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{p.type}</p>
                           </div>
                        </div>
                        <button 
                          onClick={() => removePartner(i)}
                          className="p-3 text-slate-200 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    ))}
                 </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Menu, X, Gavel, User, Heart, BookOpen, Calendar, Info, PhoneCall, Briefcase, LayoutDashboard, GraduationCap, ShieldAlert, ChevronDown, Newspaper } from 'lucide-react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { MembershipTier } from '../types';

interface UserSession {
  name: string;
  tier: MembershipTier | 'Admin';
}

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const [user, setUser] = useState<UserSession | null>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const UCLF_LOGO = "https://i.postimg.cc/TYDvMJrD/UCLF-LOGO-(1).png";

  useEffect(() => {
    const saved = localStorage.getItem('uclf_user');
    if (saved) {
      try {
        setUser(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse user session", e);
      }
    }
  }, [location.pathname]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'About', path: '/about' },
    { name: 'Membership', path: '/membership' },
    { name: 'Legal Aid', path: '/legal-aid' },
    // News & Events is handled as a dropdown separately
    { name: 'Resources', path: '/resources' },
    { name: 'Donate', path: '/donate' },
  ];

  const getDashboardLink = () => {
    if (!user) return null;
    if (user.tier === 'Admin') {
      return { path: '/admin-dashboard', label: 'Admin Portal', icon: <ShieldAlert size={16} /> };
    }
    if (user.tier === MembershipTier.FULL) {
      return { path: '/case-management', label: 'Advocate Dashboard', icon: <Briefcase size={16} /> };
    }
    if (user.tier === MembershipTier.ASSOCIATE) {
      return { path: '/associate-dashboard', label: 'Associate Dashboard', icon: <LayoutDashboard size={16} /> };
    }
    if (user.tier === MembershipTier.STUDENT) {
      return { path: '/student-dashboard', label: 'Student Hub', icon: <GraduationCap size={16} /> };
    }
    return null;
  };

  const dashboard = getDashboardLink();

  const handleLogout = () => {
    localStorage.removeItem('uclf_user');
    setUser(null);
    navigate('/');
    window.location.reload();
  };

  return (
    <nav className="bg-white shadow-md sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-24">
          <div className="flex items-center">
            <Link to="/" className="flex items-center space-x-3">
              <div className="w-16 h-16 flex items-center justify-center">
                <img src={UCLF_LOGO} alt="UCLF Logo" className="w-full h-full object-contain" />
              </div>
              <div>
                <span className="text-2xl font-black text-primary block leading-tight tracking-tighter">UCLF</span>
                <span className="text-[10px] uppercase tracking-widest text-gray-400 font-black">Uganda Christian Lawyers</span>
              </div>
            </Link>
          </div>

          <div className="hidden lg:flex items-center space-x-4">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`flex items-center space-x-1 px-3 py-2 rounded-md text-[13px] font-bold transition-colors ${
                  location.pathname === link.path
                    ? 'text-primary bg-blue-50'
                    : 'text-gray-600 hover:text-primary hover:bg-gray-50'
                }`}
              >
                {link.name}
              </Link>
            ))}

            {/* Custom Dropdown for News & Events */}
            <div className="relative" ref={dropdownRef}>
              <button
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className={`flex items-center space-x-1 px-3 py-2 rounded-md text-[13px] font-bold transition-colors ${
                  location.pathname.includes('/news') || location.pathname.includes('/events')
                    ? 'text-primary bg-blue-50'
                    : 'text-gray-600 hover:text-primary hover:bg-gray-50'
                }`}
              >
                <span>News & Events</span>
                <ChevronDown size={14} className={`transition-transform duration-200 ${isDropdownOpen ? 'rotate-180' : ''}`} />
              </button>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 mt-1 w-48 bg-white rounded-xl shadow-2xl border border-gray-100 py-2 animate-in fade-in slide-in-from-top-2 duration-200">
                  <Link
                    to="/news"
                    onClick={() => setIsDropdownOpen(false)}
                    className="flex items-center space-x-3 px-4 py-3 text-sm font-bold text-gray-600 hover:bg-blue-50 hover:text-primary transition-all"
                  >
                    <Newspaper size={16} />
                    <span>Latest News</span>
                  </Link>
                  <Link
                    to="/events"
                    onClick={() => setIsDropdownOpen(false)}
                    className="flex items-center space-x-3 px-4 py-3 text-sm font-bold text-gray-600 hover:bg-blue-50 hover:text-primary transition-all"
                  >
                    <Calendar size={16} />
                    <span>Events Calendar</span>
                  </Link>
                </div>
              )}
            </div>

            {dashboard && (
              <Link
                to={dashboard.path}
                className={`flex items-center space-x-2 px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest border transition-all ml-2 ${
                  user?.tier === 'Admin' ? 'bg-red-50 text-red-600 border-red-200 hover:bg-red-100' : 'bg-blue-50 text-primary border-primary/20 hover:bg-blue-100'
                }`}
              >
                {dashboard.icon}
                <span>{dashboard.label}</span>
              </Link>
            )}

            {!user ? (
              <Link
                to="/login"
                className="ml-4 bg-primary text-white px-5 py-2.5 rounded-lg text-sm font-semibold hover:bg-blue-800 transition-all shadow-sm"
              >
                Member Login
              </Link>
            ) : (
              <div className="flex items-center ml-4 space-x-4">
                 <div className="flex items-center space-x-3">
                   <div className={`w-8 h-8 rounded-full flex items-center justify-center font-black text-xs border ${user.tier === 'Admin' ? 'bg-red-600 text-white' : 'bg-primary text-secondary'}`}>
                      {user.name.charAt(0)}
                   </div>
                   <span className="text-xs font-bold text-gray-500 hidden xl:block">{user.name.split(' ')[0]}</span>
                 </div>
                 <button 
                  onClick={handleLogout}
                  className="text-gray-400 hover:text-red-500 transition-colors p-1"
                  title="Logout"
                 >
                   <LogOut size={18} />
                 </button>
              </div>
            )}
          </div>

          <div className="lg:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-gray-600 hover:text-primary p-2"
            >
              {isOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="lg:hidden bg-white border-t border-gray-100 animate-in slide-in-from-top duration-300">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`flex items-center space-x-3 block px-3 py-4 rounded-md text-base font-medium ${
                  location.pathname === link.path
                    ? 'text-primary bg-blue-50'
                    : 'text-gray-600 hover:text-primary hover:bg-gray-50'
                }`}
              >
                <span>{link.name}</span>
              </Link>
            ))}

            {/* Mobile News & Events Sub-menu */}
            <div className="border-t border-gray-50 mt-2 pt-2">
              <p className="px-3 py-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">News & Events</p>
              <Link
                to="/news"
                onClick={() => setIsOpen(false)}
                className="flex items-center space-x-3 px-3 py-4 rounded-md text-base font-medium text-gray-600 hover:bg-blue-50 hover:text-primary transition-all"
              >
                <Newspaper size={18} />
                <span>Latest News</span>
              </Link>
              <Link
                to="/events"
                onClick={() => setIsOpen(false)}
                className="flex items-center space-x-3 px-3 py-4 rounded-md text-base font-medium text-gray-600 hover:bg-blue-50 hover:text-primary transition-all"
              >
                <Calendar size={18} />
                <span>Events Calendar</span>
              </Link>
            </div>

            {dashboard && (
              <Link
                to={dashboard.path}
                onClick={() => setIsOpen(false)}
                className={`flex items-center space-x-3 px-3 py-4 rounded-md text-base font-bold ${user?.tier === 'Admin' ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-primary'}`}
              >
                {dashboard.icon}
                <span>{dashboard.label}</span>
              </Link>
            )}

            {!user ? (
              <Link
                to="/login"
                onClick={() => setIsOpen(false)}
                className="flex items-center justify-center space-x-2 w-full mt-4 bg-primary text-white px-3 py-3 rounded-md text-base font-medium shadow-md"
              >
                <User size={18} />
                <span>Member Login</span>
              </Link>
            ) : (
              <button
                onClick={() => { handleLogout(); setIsOpen(false); }}
                className="flex items-center space-x-3 px-3 py-4 text-red-500 hover:bg-red-50 rounded-md text-base font-bold w-full text-left"
              >
                <LogOut size={20} />
                <span>Sign Out</span>
              </button>
            )}
          </div>
        </div>
      )}
    </nav>
  );
};

const LogOut = ({ size, className }: { size?: number, className?: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/>
  </svg>
);

export default Navbar;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Lock, Mail, ArrowRight, Gavel, GraduationCap, Award, 
  ShieldCheck, AlertCircle, Loader2, Eye, EyeOff, ShieldAlert, ChevronRight
} from 'lucide-react';
import { MembershipTier } from '../types';

const Login: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const UCLF_LOGO = "https://i.postimg.cc/TYDvMJrD/UCLF-LOGO-(1).png";

  const handleSimulatedLogin = (tier: MembershipTier | 'Admin') => {
    setIsLoading(true);
    setError(null);

    setTimeout(() => {
      const mockUser = {
        name: tier === 'Admin' ? 'System Administrator' :
              tier === MembershipTier.STUDENT ? 'Student Member' : 
              tier === MembershipTier.ASSOCIATE ? 'Associate Member' : 'Counsel Advocate',
        email: `${tier.toLowerCase()}@uclf.org.ug`,
        tier: tier,
      };

      localStorage.setItem('uclf_user', JSON.stringify(mockUser));
      setIsLoading(false);

      if (tier === 'Admin') navigate('/admin-dashboard');
      else if (tier === MembershipTier.FULL) navigate('/case-management');
      else if (tier === MembershipTier.ASSOCIATE) navigate('/associate-dashboard');
      else navigate('/student-dashboard');

      window.location.reload();
    }, 1500);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError("Please use the 'Test Access' buttons below to navigate the prototype dashboards.");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
      <div className="max-w-md w-full">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center p-4 rounded-3xl mb-4">
            <img src={UCLF_LOGO} alt="UCLF Logo" className="w-32 h-32 object-contain drop-shadow-2xl" />
          </div>
          <h1 className="text-3xl font-black text-gray-900 font-serif">Member Portal</h1>
          <p className="text-gray-500 mt-2 font-medium">Access your UCLF professional workspace</p>
        </div>

        <div className="bg-white rounded-[2.5rem] shadow-2xl p-8 border border-gray-100 mb-8 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5">
            <ShieldCheck size={120} className="text-primary" />
          </div>

          <form onSubmit={handleSubmit} className="space-y-6 relative z-10">
            {error && (
              <div className="bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded-xl flex items-start text-xs font-medium animate-in fade-in duration-300">
                <AlertCircle size={16} className="mr-3 shrink-0" />
                {error}
              </div>
            )}

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest pl-1">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                  type="email" 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 outline-none focus:ring-2 focus:ring-primary/20 transition-all"
                  placeholder="name@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest pl-1">Password</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                  type={showPassword ? 'text' : 'password'}
                  className="w-full pl-12 pr-12 py-4 rounded-2xl border border-gray-200 outline-none focus:ring-2 focus:ring-primary/20 transition-all"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <button 
                  type="button" 
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-primary"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <button 
              type="submit"
              className="w-full bg-primary text-white py-4 rounded-2xl font-bold flex items-center justify-center hover:bg-blue-800 transition-all shadow-lg shadow-primary/20"
            >
              Sign In <ArrowRight size={18} className="ml-2" />
            </button>
          </form>
        </div>

        <div className="space-y-4">
          <div className="flex items-center space-x-4">
            <div className="h-px flex-grow bg-gray-200"></div>
            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Prototype Test Access</span>
            <div className="h-px flex-grow bg-gray-200"></div>
          </div>

          <div className="grid grid-cols-1 gap-3">
             <button 
              onClick={() => handleSimulatedLogin('Admin')}
              disabled={isLoading}
              className="flex items-center justify-between p-4 bg-red-50 rounded-2xl border border-red-200 hover:border-red-600 hover:shadow-md transition-all group"
            >
              <div className="flex items-center space-x-4">
                <div className="bg-red-600 p-2 rounded-xl text-white">
                  <ShieldAlert size={20} />
                </div>
                <div className="text-left">
                  <p className="text-sm font-bold text-red-900">Login as Administrator</p>
                  <p className="text-[10px] text-red-500 uppercase tracking-widest">System Management Access</p>
                </div>
              </div>
              {isLoading ? <Loader2 size={18} className="animate-spin text-red-600" /> : <ChevronRight size={18} className="text-red-300" />}
            </button>

            <button 
              onClick={() => handleSimulatedLogin(MembershipTier.FULL)}
              disabled={isLoading}
              className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-200 hover:border-primary hover:shadow-md transition-all group"
            >
              <div className="flex items-center space-x-4">
                <div className="bg-blue-50 p-2 rounded-xl text-primary group-hover:bg-primary group-hover:text-white transition-all">
                  <Gavel size={20} />
                </div>
                <div className="text-left">
                  <p className="text-sm font-bold text-gray-900">Login as Advocate</p>
                  <p className="text-[10px] text-gray-500 uppercase tracking-widest">Full Member Dashboard</p>
                </div>
              </div>
              {isLoading ? <Loader2 size={18} className="animate-spin text-primary" /> : <ChevronRight size={18} className="text-gray-300" />}
            </button>

            <button 
              onClick={() => handleSimulatedLogin(MembershipTier.ASSOCIATE)}
              disabled={isLoading}
              className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-200 hover:border-primary hover:shadow-md transition-all group"
            >
              <div className="flex items-center space-x-4">
                <div className="bg-orange-50 p-2 rounded-xl text-orange-600 group-hover:bg-orange-600 group-hover:text-white transition-all">
                  <Award size={20} />
                </div>
                <div className="text-left">
                  <p className="text-sm font-bold text-gray-900">Login as Associate</p>
                  <p className="text-[10px] text-gray-500 uppercase tracking-widest">Professional Associate Hub</p>
                </div>
              </div>
              {isLoading ? <Loader2 size={18} className="animate-spin text-orange-600" /> : <ChevronRight size={18} className="text-gray-300" />}
            </button>

            <button 
              onClick={() => handleSimulatedLogin(MembershipTier.STUDENT)}
              disabled={isLoading}
              className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-200 hover:border-primary hover:shadow-md transition-all group"
            >
              <div className="flex items-center space-x-4">
                <div className="bg-green-50 p-2 rounded-xl text-green-600 group-hover:bg-green-600 group-hover:text-white transition-all">
                  <GraduationCap size={20} />
                </div>
                <div className="text-left">
                  <p className="text-sm font-bold text-gray-900">Login as Student</p>
                  <p className="text-[10px] text-gray-500 uppercase tracking-widest">University Chapter Hub</p>
                </div>
              </div>
              {isLoading ? <Loader2 size={18} className="animate-spin text-green-600" /> : <ChevronRight size={18} className="text-gray-300" />}
            </button>
          </div>
        </div>

        <div className="mt-12 text-center">
          <p className="text-sm text-gray-500 font-medium">Not a member yet? <button onClick={() => navigate('/membership')} className="text-primary font-black hover:underline">Register Now</button></p>
        </div>
      </div>
    </div>
  );
};

export default Login;

