                   <div className="grid grid-cols-2 gap-8 mb-12">
                      <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Legal Program</p>
                         <p className="font-bold text-gray-900">{selectedCase.program}</p>
                      </div>
                      <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Current Venue</p>
                         <p className="font-bold text-gray-900">{selectedCase.courtLevel}</p>
                      </div>
                   </div>

                   <div className="space-y-6">
                      <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest border-b border-gray-100 pb-2">Case Narrative</h3>
                      <p className="text-gray-600 leading-relaxed italic">"{selectedCase.description}"</p>

                      <div className="bg-blue-50/50 p-8 rounded-[2rem] border border-blue-100 flex items-start space-x-4">
