                            <p className="text-[10px] font-black text-primary uppercase tracking-widest mb-1">Secretariat Note</p>
                            <p className="text-sm font-medium text-blue-900">Verification complete. Indigent status confirmed via Regional Hub. Pro-bono assignment pending final counsel signature.</p>
                         </div>
                      </div>
                   </div>
