                   <div className="mt-12 pt-10 border-t border-gray-200">
                      <button className="w-full py-4 bg-white border border-gray-200 text-gray-500 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center hover:bg-gray-100 transition-colors">
                        <Download size={16} className="mr-2" /> Download Dossier
                      </button>
                      <button className="w-full mt-4 py-4 bg-white border border-gray-200 text-red-500 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center hover:bg-red-50 transition-colors">
                        <Trash2 size={16} className="mr-2" /> Delete Record
                      </button>
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}
