      const saved = localStorage.getItem('uclf_news');
      if (saved) {
        setArticles(JSON.parse(saved));
      } else {
        setArticles(DEFAULT_NEWS);
        localStorage.setItem('uclf_news', JSON.stringify(DEFAULT_NEWS));
