                   <div className="flex items-center justify-between mb-10">
                      <span className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 ${getUrgencyColor(selectedCase.urgency)}`}>
                        {selectedCase.urgency} Urgency
                      </span>
                      <button onClick={() => setIsDetailModalOpen(false)} className="p-2 text-gray-400 hover:bg-gray-100 rounded-full"><X size={24} /></button>
                   </div>

                   <h2 className="text-4xl font-black text-gray-900 font-serif mb-2">{selectedCase.caseRef}</h2>
                   <p className="text-lg text-primary font-bold mb-10">Applicant: {selectedCase.requesterName}</p>

                   <div className="grid grid-cols-2 gap-8 mb-12">
                      <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Legal Program</p>
                         <p className="font-bold text-gray-900">{selectedCase.program}</p>
                      </div>
                      <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Current Venue</p>
                         <p className="font-bold text-gray-900">{selectedCase.courtLevel}</p>
                      </div>
                   </div>

                   <div className="space-y-6">
                      <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest border-b border-gray-100 pb-2">Case Narrative</h3>
                      <p className="text-gray-600 leading-relaxed italic">"{selectedCase.description}"</p>

                      <div className="bg-blue-50/50 p-8 rounded-[2rem] border border-blue-100 flex items-start space-x-4">
                         <div className="bg-primary p-3 rounded-2xl text-secondary shadow-lg shrink-0"><MessageSquare size={20} /></div>
                         <div>
                            <p className="text-[10px] font-black text-primary uppercase tracking-widest mb-1">Secretariat Note</p>
                            <p className="text-sm font-medium text-blue-900">Verification complete. Indigent status confirmed via Regional Hub. Pro-bono assignment pending final counsel signature.</p>
                         </div>
                      </div>
                   </div>
                </div>

                {/* Right: Actions */}
                <div className="w-full md:w-80 bg-gray-50 p-12 border-l border-gray-100 flex flex-col">
                   <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest mb-10">Update Workflow</h3>
                   <div className="space-y-4 flex-grow">
                      {[
                        { status: CaseStatus.ASSIGNED, color: 'bg-blue-600 text-white' },
                        { status: CaseStatus.IN_PROGRESS, color: 'bg-yellow-500 text-white' },
                        { status: CaseStatus.RESOLVED, color: 'bg-green-600 text-white' },
                        { status: CaseStatus.CLOSED, color: 'bg-gray-800 text-white' }
                      ].map(s => (
                        <button 
                          key={s.status}
                          onClick={() => updateCaseStatus(selectedCase.id, s.status)}
                          className={`w-full py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-md hover:scale-[1.03] active:scale-[0.98] ${s.color}`}
                        >
                          Mark as {s.status}
                        </button>
                      ))}
                   </div>

                   <div className="mt-12 pt-10 border-t border-gray-200">
                      <button className="w-full py-4 bg-white border border-gray-200 text-gray-500 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center hover:bg-gray-100 transition-colors">
                        <Download size={16} className="mr-2" /> Download Dossier
                      </button>
                      <button className="w-full mt-4 py-4 bg-white border border-gray-200 text-red-500 rounded-2xl text-xs font-black uppercase tracking-widest flex items-center justify-center hover:bg-red-50 transition-colors">
                        <Trash2 size={16} className="mr-2" /> Delete Record
                      </button>
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

