  { id: '1', title: 'Standard Land Purchase Agreement', category: 'Legal Templates', date: 'Oct 2023', type: 'DOC', downloadUrl: '#' },
];

const MOCK_REGISTERED_USERS = [
  { id: 'u1', name: 'Counsel Martin Sabiiti', email: 'martin.s@uclf.org.ug', tier: MembershipTier.FULL, status: 'Active', joined: 'Jan 2012', location: 'Kampala', forcePasswordChange: false },
  { id: 'u2', name: 'Jane Nakato', email: 'j.nakato@uclf.org.ug', tier: MembershipTier.ASSOCIATE, status: 'Active', joined: 'Mar 2018', location: 'Kampala', forcePasswordChange: false },
  { id: 'u3', name: 'Sarah Nakimera', email: 'sarah.n@ucu.ac.ug', tier: MembershipTier.STUDENT, status: 'Active', joined: 'Feb 2023', location: 'Mukono', forcePasswordChange: false },
  { id: 'u4', name: 'David Komakech', email: 'david.k@uclf.org.ug', tier: MembershipTier.FULL, status: 'Active', joined: 'Nov 2015', location: 'Gulu', forcePasswordChange: false },
];

const AdminDashboard: React.FC = () => {
  const navigate = useNavigate();
  const formRef = useRef<HTMLDivElement>(null);
  const resourceFormRef = useRef<HTMLDivElement>(null);
  const memberFormRef = useRef<HTMLDivElement>(null);
  const UCLF_LOGO = "https://i.postimg.cc/TYDvMJrD/UCLF-LOGO-(1).png";

  const [activeTab, setActiveTab] = useState<'gallery' | 'partners' | 'events' | 'news' | 'resources' | 'members'>('members');

  // Data States
  const [gallery, setGallery] = useState<GalleryImage[]>([]);
  const [partners, setPartners] = useState<{name: string, type: string, logoUrl: string}[]>([]);
  const [events, setEvents] = useState<Event[]>([]);
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [resources, setResources] = useState<Resource[]>([]);
  const [registeredMembers, setRegisteredMembers] = useState<any[]>([]);

  // Filtering Member States
  const [memberSearch, setMemberSearch] = useState('');
  const [memberTierFilter, setMemberTierFilter] = useState<'All' | MembershipTier>('All');

  // Member Form State
  const [isMemberFormOpen, setIsMemberFormOpen] = useState(false);
  const [editingMemberId, setEditingMemberId] = useState<string | null>(null);
  const [memberForm, setMemberForm] = useState({
    name: '',
    email: '',
    password: '',
    forcePasswordChange: true,
    tier: MembershipTier.FULL,
    status: 'Active',
    joined: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'short' }),
    location: 'Kampala'
  });

  // Gallery Form State
  const [newGalleryImage, setNewGalleryImage] = useState<Partial<GalleryImage>>({
    url: '', caption: '', category: 'General', date: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }), location: 'Kampala'
  });

  const [newPartner, setNewPartner] = useState({ name: '', type: '', logoUrl: '' });

  const [editingEventId, setEditingEventId] = useState<string | null>(null);
  const [newEvent, setNewEvent] = useState<Partial<Event>>({
    title: '', description: '', type: 'Fellowship', date: '', location: '', cleCredits: 0, capacity: 50, filled: 0, imageUrl: ''
  });

  const [editingNewsId, setEditingNewsId] = useState<string | null>(null);
  const [newArticle, setNewArticle] = useState<Partial<NewsArticle>>({
    title: '', excerpt: '', content: '', date: '', imageUrls: [''], category: 'General'
  });

  const [editingResourceId, setEditingResourceId] = useState<string | null>(null);
  const [newResource, setNewResource] = useState<Partial<Resource>>({
    title: '', category: 'Legal Templates', date: '', type: 'PDF', downloadUrl: '', description: ''
  });

  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => {
    const userStr = localStorage.getItem('uclf_user');
    if (!userStr || JSON.parse(userStr).tier !== 'Admin') {
      navigate('/login');
      return;
    }

    const loadData = (key: string, initial: any, setter: Function) => {
      const saved = localStorage.getItem(key);
      if (saved) setter(JSON.parse(saved));
      else {
        setter(initial);
        localStorage.setItem(key, JSON.stringify(initial));
      }
    };

    loadData('uclf_gallery_data', DEFAULT_GALLERY, setGallery);
    loadData('uclf_partners', DEFAULT_PARTNERS, setPartners);
    loadData('uclf_events', INITIAL_EVENTS, setEvents);
    loadData('uclf_news', INITIAL_NEWS, setNews);
    loadData('uclf_resources', INITIAL_RESOURCES, setResources);
    loadData('uclf_registered_members', MOCK_REGISTERED_USERS, setRegisteredMembers);
  }, [navigate]);

  const showNotice = (msg: string, type: 'success' | 'error' = 'success') => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleLogout = () => {
    localStorage.removeItem('uclf_user');
    navigate('/login');
    window.location.reload();
  };

  const handleSaveMember = () => {
    if (!memberForm.name || !memberForm.email) {
      showNotice('Identity and Email are mandatory', 'error');
      return;
    }

    let updated: any[];
    if (editingMemberId) {
      updated = registeredMembers.map(m => m.id === editingMemberId ? { ...memberForm, id: editingMemberId } : m);
      showNotice('Member record updated');
    } else {
      // In a real app, password would be hashed. For prototype, we store as is.
      updated = [{ ...memberForm, id: 'u' + Date.now() }, ...registeredMembers];
      showNotice('New member enrolled with default credentials');
    }

    setRegisteredMembers(updated);
    localStorage.setItem('uclf_registered_members', JSON.stringify(updated));
    resetMemberForm();
  };

  const resetMemberForm = () => {
    setEditingMemberId(null);
    setIsMemberFormOpen(false);
    setMemberForm({
      name: '',
      email: '',
      password: '',
      forcePasswordChange: true,
      tier: MembershipTier.FULL,
      status: 'Active',
      joined: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'short' }),
      location: 'Kampala'
    });
  };

  const startEditMember = (m: any) => {
    setEditingMemberId(m.id);
    setMemberForm({
        ...m,
        password: m.password || '', // Keep existing or empty
        forcePasswordChange: m.forcePasswordChange ?? true
    });
    setIsMemberFormOpen(true);
    memberFormRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const deleteMember = (id: string) => {
    if (window.confirm('Revoke all access for this member? This action is immediate.')) {
        const updated = registeredMembers.filter(m => m.id !== id);
        setRegisteredMembers(updated);
        localStorage.setItem('uclf_registered_members', JSON.stringify(updated));
        showNotice('Member credentials revoked');
    }
  };

  const filteredMembers = useMemo(() => {
    return registeredMembers.filter(m => {
        const matchesSearch = m.name.toLowerCase().includes(memberSearch.toLowerCase()) || m.email.toLowerCase().includes(memberSearch.toLowerCase());
        const matchesTier = memberTierFilter === 'All' || m.tier === memberTierFilter;
        return matchesSearch && matchesTier;
    });
  }, [memberSearch, memberTierFilter, registeredMembers]);

  // Gallery, Partners, News, etc. handlers omitted for brevity but retained in functionality
  const addImageToGallery = () => { if (!newGalleryImage.url || !newGalleryImage.caption) return; const updated = [{...newGalleryImage as GalleryImage, id: 'g'+Date.now()}, ...gallery]; setGallery(updated); localStorage.setItem('uclf_gallery_data', JSON.stringify(updated)); setNewGalleryImage({url:'', caption:'', category:'General', location:'Kampala'}); showNotice('Published'); };
  const removeImageFromGallery = (id: string) => { const updated = gallery.filter(img => img.id !== id); setGallery(updated); localStorage.setItem('uclf_gallery_data', JSON.stringify(updated)); showNotice('Removed'); };
  const addPartner = () => { if (!newPartner.name || !newPartner.logoUrl) return; const updated = [newPartner, ...partners]; setPartners(updated); localStorage.setItem('uclf_partners', JSON.stringify(updated)); setNewPartner({ name: '', type: '', logoUrl: '' }); showNotice('Partner added'); };
  const removePartner = (index: number) => { const updated = partners.filter((_, i) => i !== index); setPartners(updated); localStorage.setItem('uclf_partners', JSON.stringify(updated)); showNotice('Partner removed'); };
  const addEvent = () => { if (!newEvent.title) return; const updated = [{...newEvent as Event, id:'e'+Date.now()}, ...events]; setEvents(updated); localStorage.setItem('uclf_events', JSON.stringify(updated)); showNotice('Event published'); };
  const addNews = () => { if (!newArticle.title) return; const updated = [{...newArticle as NewsArticle, id:'n'+Date.now()}, ...news]; setNews(updated); localStorage.setItem('uclf_news', JSON.stringify(updated)); showNotice('News published'); };
  const addResource = () => { if (!newResource.title) return; const updated = [{...newResource as Resource, id:'r'+Date.now()}, ...resources]; setResources(updated); localStorage.setItem('uclf_resources', JSON.stringify(updated)); showNotice('Resource published'); };

  return (
