                       <button onClick={resetMemberForm} className="flex-1 bg-slate-100 text-slate-500 py-5 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all">Discard Changes</button>
                    </div>
                  </div>
