                                              <span className="flex items-center text-[8px] font-black text-red-500 uppercase tracking-widest bg-red-50 px-2 py-1 rounded border border-red-100">
                                                <AlertTriangle size={10} className="mr-1" /> Change Required
                                              </span>
                                            ) : (
                                              <span className="flex items-center text-[8px] font-black text-emerald-500 uppercase tracking-widest bg-emerald-50 px-2 py-1 rounded border border-emerald-100">
                                                <CheckCircle size={10} className="mr-1" /> Credential Verified
                                              </span>
                                            )}
