import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Lock, Mail, ArrowRight, Gavel, GraduationCap, Award, 
  ShieldCheck, AlertCircle, Loader2, Eye, EyeOff, ShieldAlert, ChevronRight,
  ShieldCheck as ShieldIcon, RefreshCcw
} from 'lucide-react';
import { MembershipTier } from '../types';

const Login: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // New Credential Change Flow States
  const [showChangePassword, setShowChangePassword] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [pendingUser, setPendingUser] = useState<any>(null);

  const UCLF_LOGO = "https://i.postimg.cc/TYDvMJrD/UCLF-LOGO-(1).png";

  const handleSimulatedLogin = (tier: MembershipTier | 'Admin') => {
    setIsLoading(true);
    setError(null);

    setTimeout(() => {
      // Find user in registry to check for force password change
      const registryStr = localStorage.getItem('uclf_registered_members');
      const registry = registryStr ? JSON.parse(registryStr) : [];
      const userMail = `${tier.toLowerCase()}@uclf.org.ug`;
      const regUser = registry.find((u: any) => u.email.toLowerCase() === userMail.toLowerCase());

      const mockUser = {
        name: tier === 'Admin' ? 'System Administrator' :
              tier === MembershipTier.STUDENT ? 'Student Member' : 
              tier === MembershipTier.ASSOCIATE ? 'Associate Member' : 'Counsel Advocate',
        email: userMail,
        tier: tier,
        forcePasswordChange: regUser?.forcePasswordChange ?? false
      };

      if (mockUser.forcePasswordChange) {
        setPendingUser(mockUser);
        setShowChangePassword(true);
        setIsLoading(false);
      } else {
        localStorage.setItem('uclf_user', JSON.stringify(mockUser));
        completeLogin(tier);
      }
    }, 1500);
  };

  const handlePasswordReset = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      setError("Credentials do not match.");
      return;
    }
    if (newPassword.length < 6) {
      setError("Credential must be at least 6 characters.");
      return;
    }

    setIsLoading(true);
    setTimeout(() => {
      // Update registry to reflect change
      const registryStr = localStorage.getItem('uclf_registered_members');
      if (registryStr) {
        const registry = JSON.parse(registryStr);
        const updated = registry.map((u: any) => 
          u.email === pendingUser.email ? { ...u, forcePasswordChange: false, password: newPassword } : u
        );
        localStorage.setItem('uclf_registered_members', JSON.stringify(updated));
      }

      const finalUser = { ...pendingUser, forcePasswordChange: false };
      localStorage.setItem('uclf_user', JSON.stringify(finalUser));
      completeLogin(finalUser.tier);
    }, 1500);
  };

  const completeLogin = (tier: string) => {
    setIsLoading(false);
    if (tier === 'Admin') navigate('/admin-dashboard');
    else if (tier === MembershipTier.FULL) navigate('/case-management');
    else if (tier === MembershipTier.ASSOCIATE) navigate('/associate-dashboard');
    else navigate('/student-dashboard');
    window.location.reload();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError("Use 'Test Access' buttons for prototype navigation.");
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
      <div className="max-w-md w-full">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center p-4 rounded-3xl mb-4">
            <img src={UCLF_LOGO} alt="UCLF Logo" className="w-32 h-32 object-contain drop-shadow-2xl" />
          </div>
          <h1 className="text-3xl font-black text-gray-900 font-serif">Member Portal</h1>
          <p className="text-gray-500 mt-2 font-medium">Access your UCLF professional workspace</p>
        </div>

        <div className="bg-white rounded-[2.5rem] shadow-2xl p-8 border border-gray-100 mb-8 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5">
            <ShieldCheck size={120} className="text-primary" />
          </div>

          {!showChangePassword ? (
            <form onSubmit={handleSubmit} className="space-y-6 relative z-10">
              {error && (
                <div className="bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded-xl flex items-start text-xs font-medium animate-in fade-in duration-300">
                  <AlertCircle size={16} className="mr-3 shrink-0" />
                  {error}
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest pl-1">Email Address</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                  <input 
                    type="email" 
                    className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 outline-none focus:ring-2 focus:ring-primary/20 transition-all font-bold"
                    placeholder="name@uclf.org.ug"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest pl-1">Password</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                  <input 
                    type={showPassword ? 'text' : 'password'}
                    className="w-full pl-12 pr-12 py-4 rounded-2xl border border-gray-200 outline-none focus:ring-2 focus:ring-primary/20 transition-all font-bold"
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                  />
                  <button 
                    type="button" 
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-primary"
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-primary text-white py-4 rounded-2xl font-bold flex items-center justify-center hover:bg-blue-800 transition-all shadow-lg shadow-primary/20"
              >
                Sign In <ArrowRight size={18} className="ml-2" />
              </button>
            </form>
          ) : (
            <form onSubmit={handlePasswordReset} className="space-y-6 relative z-10 animate-in slide-in-from-right duration-500">
               <div className="text-center mb-6">
                 <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4 border border-red-100 shadow-inner">
                   <RefreshCcw size={28} className="animate-spin-slow" />
                 </div>
                 <h2 className="text-xl font-black text-gray-900">Credential Update Required</h2>
                 <p className="text-xs text-gray-500 mt-1 uppercase font-black tracking-widest">Mandatory First-Time Refresh</p>
               </div>

               {error && (
                <div className="bg-red-50 border border-red-100 text-red-800 p-4 rounded-xl flex items-start text-xs font-bold animate-shake">
                  <AlertCircle size={16} className="mr-3 shrink-0" />
                  {error}
                </div>
              )}

               <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest pl-1">Secure New Password</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                  <input 
                    required
                    type="password" 
                    className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 outline-none focus:ring-4 focus:ring-red-500/5 transition-all font-bold"
                    placeholder="New Secure Password"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest pl-1">Confirm Credential</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                  <input 
                    required
                    type="password" 
                    className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 outline-none focus:ring-4 focus:ring-red-500/5 transition-all font-bold"
                    placeholder="Repeat Password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                  />
                </div>
              </div>

              <button 
                type="submit"
                disabled={isLoading}
                className="w-full bg-red-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center hover:bg-red-700 transition-all shadow-xl shadow-red-900/20"
              >
                {isLoading ? <Loader2 className="animate-spin" /> : <>Authorize & Apply Change <ArrowRight size={16} className="ml-2" /></>}
              </button>
            </form>
          )}
        </div>

        {!showChangePassword && (
          <div className="space-y-4">
            <div className="flex items-center space-x-4">
              <div className="h-px flex-grow bg-gray-200"></div>
              <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Registry Test Access</span>
              <div className="h-px flex-grow bg-gray-200"></div>
            </div>

            <div className="grid grid-cols-1 gap-3">
              <button onClick={() => handleSimulatedLogin('Admin')} disabled={isLoading} className="flex items-center justify-between p-4 bg-red-50 rounded-2xl border border-red-200 hover:border-red-600 hover:shadow-md transition-all group">
                <div className="flex items-center space-x-4">
                  <div className="bg-red-600 p-2 rounded-xl text-white"><ShieldAlert size={20} /></div>
                  <div className="text-left">
                    <p className="text-sm font-bold text-red-900">Administrator Console</p>
                  </div>
                </div>
                {isLoading ? <Loader2 size={18} className="animate-spin text-red-600" /> : <ChevronRight size={18} className="text-red-300" />}
              </button>

              <button onClick={() => handleSimulatedLogin(MembershipTier.FULL)} disabled={isLoading} className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-200 hover:border-primary hover:shadow-md transition-all group">
                <div className="flex items-center space-x-4">
                  <div className="bg-blue-50 p-2 rounded-xl text-primary group-hover:bg-primary group-hover:text-white transition-all"><Gavel size={20} /></div>
                  <div className="text-left"><p className="text-sm font-bold text-gray-900">Advocate Portal</p></div>
                </div>
                {isLoading ? <Loader2 size={18} className="animate-spin text-primary" /> : <ChevronRight size={18} className="text-gray-300" />}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

