import React, { useState, useEffect, useRef } from 'react';
import { MessageCircle, X, Send, User, ShieldCheck, CheckCheck, Loader2, Sparkles } from 'lucide-react';
import { getChatbotResponse } from '../geminiService';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
}

const WhatsAppChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    {
      role: 'model',
      text: "Hello! I'm your UCLF Concierge. How can I assist you with membership or legal aid inquiries today? 🙏",
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const UCLF_LOGO = "https://i.postimg.cc/TYDvMJrD/UCLF-LOGO-(1).png";

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userText = input;
    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    setMessages(prev => [...prev, { role: 'user', text: userText, timestamp: time }]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }] as [{ text: string }]
    }));

    const response = await getChatbotResponse(userText, history);

    setMessages(prev => [...prev, { 
      role: 'model', 
      text: response, 
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) 
    }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[2000] flex flex-col items-end">
      {/* Chat Window - Shortened height (approx 470px) */}
      {isOpen && (
        <div className="mb-4 w-[90vw] sm:w-[380px] h-[470px] bg-white rounded-[2rem] shadow-2xl flex flex-col overflow-hidden border border-gray-100 animate-in slide-in-from-bottom-6 duration-300">
          {/* Header - UCLF Blue */}
          <header className="bg-primary p-6 text-white shrink-0">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="relative">
                  <div className="w-12 h-12 rounded-full bg-white p-1 overflow-hidden">
                    <img src={UCLF_LOGO} alt="Logo" className="w-full h-full object-contain" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-3 h-3 bg-secondary rounded-full border-2 border-primary"></div>
                </div>
                <div>
                  <h3 className="font-bold flex items-center">
                    UCLF Concierge
                    <ShieldCheck size={14} className="ml-1.5 text-blue-400" fill="currentColor" />
                  </h3>
                  <p className="text-[10px] text-blue-100 opacity-80 flex items-center uppercase font-black tracking-widest">
                    <span className="w-1 h-1 rounded-full bg-green-400 mr-1.5 animate-pulse"></span>
                    Online AI Assistant
                  </p>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <X size={24} />
              </button>
            </div>
          </header>

          {/* Messages Area */}
          <div 
            ref={scrollRef}
            className="flex-grow overflow-y-auto p-6 space-y-4 bg-gray-50 custom-scrollbar"
            style={{ backgroundImage: 'linear-gradient(rgba(255,255,255,0.92), rgba(255,255,255,0.92)), url("https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png")', backgroundSize: 'contain' }}
          >
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3.5 rounded-2xl shadow-sm text-sm relative ${
                  m.role === 'user' 
                    ? 'bg-primary text-white rounded-tr-none' 
                    : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
                }`}>
                  <p className="leading-relaxed font-medium">{m.text}</p>
                  <div className={`flex items-center justify-end space-x-1 mt-1 ${m.role === 'user' ? 'opacity-60' : 'opacity-40'}`}>
                    <span className="text-[9px] font-bold">{m.timestamp}</span>
                    {m.role === 'user' && <CheckCheck size={12} />}
                  </div>
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white p-3.5 rounded-2xl rounded-tl-none shadow-sm flex space-x-1 items-center border border-gray-100">
                  <div className="w-1.5 h-1.5 bg-primary/30 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-primary/30 rounded-full animate-bounce delay-75"></div>
                  <div className="w-1.5 h-1.5 bg-primary/30 rounded-full animate-bounce delay-150"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <form onSubmit={handleSend} className="p-4 bg-gray-100 flex items-center space-x-3 shrink-0">
            <input 
              type="text" 
              className="flex-grow bg-white px-5 py-3 rounded-full text-sm outline-none shadow-sm focus:ring-2 focus:ring-primary/20 transition-all font-medium"
              placeholder="Ask a question..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              disabled={isTyping}
            />
            <button 
              type="submit"
              disabled={!input.trim() || isTyping}
              className={`p-3 rounded-full shadow-lg transition-all active:scale-95 ${
                !input.trim() || isTyping ? 'bg-gray-300' : 'bg-primary text-white hover:brightness-110'
              }`}
            >
              {isTyping ? <Loader2 className="animate-spin" size={20} /> : <Send size={20} />}
            </button>
          </form>
        </div>
      )}

      {/* Floating Button - UCLF Blue/White */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-16 h-16 rounded-full flex items-center justify-center shadow-2xl transition-all duration-500 hover:scale-110 active:scale-95 group ${
          isOpen ? 'bg-red-500 rotate-90 text-white' : 'bg-primary text-white'
        }`}
      >
        {isOpen ? (
          <X size={32} />
        ) : (
          <Sparkles className="text-secondary group-hover:scale-110 transition-transform" size={32} />
        )}
      </button>
    </div>
  );
};

export default WhatsAppChatbot;

