import { GoogleGenAI } from "@google/genai";

export async function getLegalAssistantResponse(prompt: string) {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: "You are an AI assistant for the Uganda Christian Lawyers Fraternity. You help summarize legal concepts, explain Christian legal ethics, and provide preliminary guidance based on Ugandan law and Christian values. Always include a disclaimer that you are an AI and not a lawyer providing professional legal advice.",
      }
    });
    return response.text || "I'm sorry, I couldn't process that request.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error connecting to AI service. Please ensure your environment variables are configured correctly.";
  }
}

export async function getChatbotResponse(prompt: string, history: { role: 'user' | 'model', parts: [{ text: string }] }[]) {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Convert history to compatible format for generateContent
    const contents = history.map(h => ({
      role: h.role,
      parts: h.parts
    }));
    contents.push({ role: 'user', parts: [{ text: prompt }] });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: contents,
      config: {
        systemInstruction: `STRICT PROTOCOL: You are the UCLF Official Concierge. 
        KNOWLEDGE BASE LIMITS:
        - Membership tiers: Student (50k), Associate (150k), Full (200k).
        - Legal Aid: Exclusively for indigent (widows, orphans, refugees). Requires regional verification.
        - Regions: Kampala, Gulu, Kasese, Arua.
        - Mission: Proverbs 31:9 - "Speak up and judge fairly."

        STRICT RULE: Only answer questions found in this knowledge base. 
        If a question is about something ELSE (e.g., cooking, generic history, personal advice, or non-UCLF legal issues), 
        respond politely and humanly exactly like this: "I apologize, but I don't have that specific information in my current records. I'm here to assist with UCLF membership and legal aid inquiries! How can I help you with those today?"

        DO NOT use asterisks (*) or bolding in your response. Keep it brief and friendly.`,
      }
    });
    return response.text || "I'm sorry, I don't have an answer for that yet. Can I help with something else?";
  } catch (error) {
    console.error("Chatbot Error:", error);
    return "I'm having a bit of trouble connecting. Please try again in a moment! 🙏";
  }
}

