import React, { useState, useEffect, useRef } from 'react';
import { X, Send, CheckCheck, Loader2, Sparkles, Bot } from 'lucide-react';
import { getChatbotResponse } from '../geminiService';

interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: string;
  isTypingEffect?: boolean;
}

const TypewriterText: React.FC<{ text: string; onComplete?: () => void }> = ({ text, onComplete }) => {
  const [displayedText, setDisplayedText] = useState('');
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (index < text.length) {
      // Create a slightly irregular, elaborate typing speed (20ms-50ms per char)
      const speed = Math.floor(Math.random() * 30) + 20; 
      const timeout = setTimeout(() => {
        setDisplayedText((prev) => prev + text[index]);
        setIndex((prev) => prev + 1);
      }, speed);
      return () => clearTimeout(timeout);
    } else if (onComplete) {
      onComplete();
    }
  }, [index, text, onComplete]);

  // Safely render the text which may contain <b> tags from the AI
  return <div dangerouslySetInnerHTML={{ __html: displayedText }} />;
};

